/* ============================================================================
   studyUPSC — application logic (vanilla JS, no dependencies)
   ----------------------------------------------------------------------------
   * hash router      #/  #/paper/{nav}  #/topic/{nav}  #/doc/{rel}  #/tracker
   * syllabus sidebar with per-paper progress
   * content file-tree from window.CONTENT_INDEX (generated by cli/generate.mjs)
   * instant client-side search (syllabus + files + full-text of notes)
   * LocalStorage revision checklist with % tracker
   ========================================================================== */
(function () {
  'use strict';

  var $ = function (sel, root) { return (root || document).querySelector(sel); };
  var $$ = function (sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); };

  var DATA = window.SYLLABUS_DATA;
  var SECTIONS = window.CONTENT_SECTIONS || [];
  var INDEX = window.CONTENT_INDEX || [];
  var DIRS = window.CONTENT_DIRS || [];
  var SEARCH_DOCS = window.SEARCH_DATA || [];

  var STORE_KEY = 'studyupsc-progress-v1';
  var THEME_KEY = 'studyupsc-theme';
  var EXPAND_KEY = 'studyupsc-expanded';

  /* ------------------------------------------------------------------ */
  /*  Small utils                                                        */
  /* ------------------------------------------------------------------ */
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function fmtBytes(n) {
    if (n < 1024) return n + ' B';
    if (n < 1048576) return (n / 1024).toFixed(1) + ' KB';
    return (n / 1048576).toFixed(1) + ' MB';
  }
  function debounce(fn, ms) {
    var t; return function () { var a = arguments; clearTimeout(t); t = setTimeout(function () { fn.apply(null, a); }, ms); };
  }
  function fileExt(name) {
    var i = name.lastIndexOf('.');
    return i === -1 ? '' : name.slice(i + 1).toLowerCase();
  }
  function humanTitle(slug) {
    return slug.replace(/[-_]+/g, ' ').replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  }

  /* ---------- router ---------- */
  function safeDecode(s) { try { return decodeURIComponent(s); } catch (e) { return s; } }
  function normalizeNav(nav) {
    if (!nav) return '';
    nav = String(nav).trim().replace(/^\/+|\/+$/g, '').replace(/\/+/g, '/');
    return safeDecode(nav);
  }
  function parseHash() {
    var raw = (location.hash || '').trim();
    if (!raw || raw === '#') return { page: 'home' };
    var h = raw.replace(/^#\/?/, '');
    if (!h) return { page: 'home' };
    // Remove trailing slash for routing (but preserve query string slash handling)
    // Split off query before slash logic for search/tracker
    var qIdx = h.indexOf('?');
    var hNoQ = qIdx === -1 ? h : h.slice(0, qIdx);
    var queryPart = qIdx === -1 ? '' : h.slice(qIdx);
    if (hNoQ.length > 1 && hNoQ.charAt(hNoQ.length - 1) === '/') hNoQ = hNoQ.replace(/\/+$/, '');
    var slash = hNoQ.indexOf('/');
    var first = slash === -1 ? hNoQ : hNoQ.slice(0, slash);
    var rest = slash === -1 ? '' : hNoQ.slice(slash + 1);
    // rest may be encodeURIComponent-encoded (e.g. doc rel contains slashes encoded)
    if (first === 'paper' && rest) return { page: 'paper', nav: normalizeNav(safeDecode(rest)) };
    if (first === 'topic' && rest) {
      var dec = safeDecode(rest);
      var secIdx = dec.indexOf('/section/');
      if (secIdx !== -1) return { page: 'topic', nav: normalizeNav(dec.slice(0, secIdx)), section: dec.slice(secIdx + 9) };
      return { page: 'topic', nav: normalizeNav(dec) };
    }
    if (first === 'doc' && rest) {
      // For doc, the rel may have been in hNoQ without query; but doc rel never has query
      return { page: 'doc', rel: safeDecode(rest) };
    }
    if (first === 'tracker') return { page: 'tracker' };
    if (first === 'search') {
      var q = '';
      var m = raw.match(/[?&]q=([^&#]*)/);
      if (m) q = safeDecode(m[1].replace(/\+/g, ' '));
      // also handle rest as q if provided as /search/<term> fallback
      if (!q && rest) q = safeDecode(rest);
      return { page: 'search', q: q };
    }
    if (first === '' ) return { page: 'home' };
    return { page: 'home' };
  }
  function go(hash) {
    var h = String(hash || '');
    if (h.charAt(0) !== '#') h = '#/' + h.replace(/^\/+/, '');
    if (location.hash === h) { render(); }
    else location.hash = h;
  }
  function navHref(kind, nav) {
    // kind: 'paper' | 'topic' | 'doc'
    if (kind === 'doc') return '#/doc/' + encodeURIComponent(nav);
    if (kind === 'paper') return '#/paper/' + encodeURIComponent(nav);
    return '#/topic/' + encodeURIComponent(nav);
  }

  /* ---------- syllabus lookup ---------- */
  var ALL_NODES = [];
  (function collect() {
    function walk(n, pathArr) {
      ALL_NODES.push(n);
      (n.sub || []).forEach(function (c) { walk(c, pathArr); });
    }
    DATA.papers.forEach(function (p) { walk(p, []); });
  })();
  var NODE_BY_NAV = {};
  ALL_NODES.forEach(function (n) { NODE_BY_NAV[n.nav] = n; });

  /* ---------- canonical numbering (matches homepage steps + book parts) --- */
  var NUM_BY_NAV = {};
  (function numberTree() {
    DATA.papers.forEach(function (p, pi) {
      var pn = String(pi + 1);
      NUM_BY_NAV[p.nav] = pn;
      (function walk(kids, prefix) {
        (kids || []).forEach(function (c, i) {
          var n = prefix + '.' + (i + 1);
          NUM_BY_NAV[c.nav] = n;
          if (c.sub && c.sub.length) walk(c.sub, n);
        });
      })(p.sub || [], pn);
    });
  })();
  function numOf(nav) { return NUM_BY_NAV[nav] || ''; }
  function numBadge(nav, small) {
    var n = numOf(nav);
    if (!n) return '';
    return '<span class="su-num' + (small ? ' sm' : '') + '" aria-hidden="true">' + esc(n) + '</span>';
  }

  /* ---------- ordered leaf sequence (powers Up-next + Continue) ---------- */
  var LEAVES = [];
  (function collectLeaves() {
    function walk(n) {
      if (isLeaf(n)) LEAVES.push(n);
      else (n.sub || []).forEach(walk);
    }
    DATA.papers.forEach(walk);
  })();
  function leafIndex(nav) {
    for (var i = 0; i < LEAVES.length; i++) if (LEAVES[i].nav === nav) return i;
    return -1;
  }
  var LAST_KEY = 'studyupsc-last-v1';
  function getLastVisit() {
    try { return JSON.parse(localStorage.getItem(LAST_KEY)) || null; } catch (e) { return null; }
  }
  function recordVisit(obj) {
    try {
      obj.ts = Date.now();
      localStorage.setItem(LAST_KEY, JSON.stringify(obj));
    } catch (e) { /* private mode */ }
  }
  function markReadRel(rel) {
    try { if (window.Study) window.Study.markRead(rel); } catch (e) { /* study.js optional */ }
  }
  function crumbsFor(nav) {
    var parts = nav.split('/'), out = [];
    var acc = [];
    parts.forEach(function (p) {
      acc.push(p);
      var n = NODE_BY_NAV[acc.join('/')];
      out.push({ nav: acc.join('/'), title: n ? n.title : humanTitle(p) });
    });
    return out;
  }
  function isLeaf(n) { return !(n.sub && n.sub.length); }
  function sectionMeta(seg) {
    for (var i = 0; i < SECTIONS.length; i++) if (SECTIONS[i].id === seg) return SECTIONS[i];
    return null;
  }

  /* ------------------------------------------------------------------ */
  /*  Revision tracker (LocalStorage)                                    */
  /* ------------------------------------------------------------------ */
  var progress = {};
  try { progress = JSON.parse(localStorage.getItem(STORE_KEY)) || {}; } catch (e) { progress = {}; }

  function saveProgress() {
    try { localStorage.setItem(STORE_KEY, JSON.stringify(progress)); } catch (e) { /* quota */ }
  }
  function nodeProgress(n) {
    if (isLeaf(n)) {
      var done = progress[n.nav] === 1 ? 1 : 0;
      return { done: done, total: 1, pct: done ? 100 : 0 };
    }
    var d = 0, t = 0;
    (n.sub || []).forEach(function (c) {
      var r = nodeProgress(c); d += r.done; t += r.total;
    });
    return { done: d, total: t, pct: t ? Math.round(100 * d / t) : 0 };
  }
  function paperProgress(paper) { return nodeProgress(paper); }
  function overallProgress() {
    var d = 0, t = 0;
    DATA.papers.forEach(function (p) { var r = nodeProgress(p); d += r.done; t += r.total; });
    return { done: d, total: t, pct: t ? Math.round(100 * d / t) : 0 };
  }
  function toggleNode(nav) {
    if (progress[nav] === 1) delete progress[nav]; else progress[nav] = 1;
    saveProgress();
    renderSidebar();
    render();
    updateFavicon();
  }
  function leafCheckbox(nav) {
    return '<input type="checkbox" class="tracker-cb h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" ' +
      (progress[nav] === 1 ? 'checked' : '') + ' data-nav="' + esc(nav) + '" aria-label="Mark complete">';
  }
  function progressBar(pct, cls) {
    cls = cls || 'bg-gradient-to-r from-indigo-500 to-violet-500';
    return '<div class="h-1.5 w-full rounded-full bg-slate-200 dark:bg-slate-700 overflow-hidden">' +
      '<div class="h-full rounded-full ' + cls + ' transition-all duration-500" style="width:' + Math.max(2, pct) + '%"></div></div>';
  }
  function updateFavicon() {
    var o = overallProgress();
    var fav = $('#favicon-progress');
    try {
      var c = document.createElement('canvas'); c.width = 64; c.height = 64;
      var g = c.getContext && c.getContext('2d');
      if (!g) return;
      g.fillStyle = '#0f172a'; g.beginPath(); g.arc(32, 32, 30, 0, 7); g.fill();
      g.strokeStyle = '#f59e0b'; g.lineWidth = 6;
      g.beginPath(); g.arc(32, 32, 30, -Math.PI / 2, -Math.PI / 2 + 2 * Math.PI * (o.pct / 100)); g.stroke();
      if (fav) fav.href = c.toDataURL();
    } catch (e) { /* favicon is decorative — never block the app on it */ }
  }

  /* ------------------------------------------------------------------ */
  /*  Theme                                                              */
  /* ------------------------------------------------------------------ */
  function applyTheme() {
    var dark = localStorage.getItem(THEME_KEY) === 'dark';
    document.documentElement.classList.toggle('dark', dark);
    var b = $('#theme-toggle');
    if (b) b.innerHTML = dark ? sunIcon() : moonIcon();
  }
  function toggleTheme() {
    var dark = !document.documentElement.classList.contains('dark');
    localStorage.setItem(THEME_KEY, dark ? 'dark' : 'light');
    applyTheme();
  }
  function sunIcon() { return '<svg class="w-5 h-5" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path stroke-linecap="round" d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>'; }
  function moonIcon() { return '<svg class="w-5 h-5" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>'; }

  /* ------------------------------------------------------------------ */
  /*  Sidebar                                                             */
  /* ------------------------------------------------------------------ */
  function loadExpanded() {
    var e = {};
    try { e = JSON.parse(localStorage.getItem(EXPAND_KEY)) || {}; } catch (err) { e = {}; }
    return e;
  }
  var expanded = loadExpanded();
  function setExpanded(key, val) {
    if (val) expanded[key] = 1; else delete expanded[key];
    try { localStorage.setItem(EXPAND_KEY, JSON.stringify(expanded)); } catch (e) { /* noop */ }
    renderSidebar();
  }

  function treeIcon(n) {
    return n.sub && n.sub.length ? '<svg class="w-3.5 h-3.5 text-slate-400 shrink-0 transition-transform" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>'
      : '<span class="w-3.5 shrink-0 text-[10px] text-slate-400">•</span>';
  }

  function syncTopNavActive(cur) {
    try {
      var tb = document.getElementById('nav-tracker');
      var bb = document.getElementById('nav-book');
      if (tb) { if (cur && cur.page === 'tracker') tb.setAttribute('aria-current','page'); else tb.removeAttribute('aria-current'); }
      if (bb) bb.removeAttribute('aria-current');
      // sidebar toggle aria
      var sb = document.getElementById('sidebar-toggle');
      if (sb) sb.setAttribute('aria-expanded', document.body.classList.contains('sidebar-open') ? 'true' : 'false');
    } catch(e){}
  }
  function renderSidebar() {
    var box = $('#sidebar');
    if (!box) return;
    var html = '';
    var o = overallProgress();
    var cur = parseHash();
    var curNav = cur.nav || '';
    html += '<div class="px-4 pt-5 pb-3 flex items-center gap-3">' +
      '<span class="brand-tile" style="width:40px;height:40px;font-size:15px" aria-hidden="true">SU</span>' +
      '<div><div class="font-display font-extrabold text-slate-900 dark:text-white leading-tight">studyUPSC</div>' +
      '<div class="text-[11px] text-slate-500 dark:text-slate-400">UPSC CSE Prep Portal</div></div></div>';
    html += '<div class="mx-4 mb-3 rounded-2xl border border-slate-200 dark:border-slate-800 bg-gradient-to-br from-indigo-50 to-white dark:from-indigo-950/40 dark:to-slate-900 p-3" role="status" aria-live="polite">' +
      '<div class="flex items-center justify-between text-[11px] font-semibold text-slate-500 dark:text-slate-400"><span>Overall syllabus</span>' +
      '<span class="font-bold ' + (o.pct === 100 ? 'text-emerald-500' : 'text-indigo-600 dark:text-indigo-400') + '">' + o.pct + '%</span></div>' +
      '<div class="mt-1.5" aria-hidden="true">' + progressBar(o.pct, o.pct === 100 ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-violet-500') + '</div>' +
      '<div class="mt-1.5 text-[10.5px] text-slate-400">' + o.done + ' of ' + o.total + ' topics done</div></div>';

    html += '<nav class="flex-1 overflow-y-auto px-2 pb-4" id="sidebar-tree" role="tree" aria-label="Syllabus">';
    DATA.papers.forEach(function (paper) {
      var pr = paperProgress(paper);
      var open = expanded['p:' + paper.id];
      var paperActive = curNav === paper.nav || curNav.indexOf(paper.nav + '/') === 0;
      html += '<div class="mt-1" role="treeitem" aria-expanded="' + (open ? 'true' : 'false') + '">';
      html += '<div class="flex items-center gap-1 rounded-lg px-2 py-1.5 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer select-none ' + (paperActive ? 'nav-active' : '') + '" data-expand="p:' + paper.id + '" role="button" tabindex="0" aria-expanded="' + (open ? 'true' : 'false') + '" aria-controls="paper-' + esc(paper.id) + '">' +
        '<span class="chev ' + (open ? 'rotate-90' : '') + '" aria-hidden="true">' + treeIcon(paper) + '</span>' +
        numBadge(paper.nav) +
        '<a href="' + navHref('paper', paper.nav) + '" class="flex-1 truncate text-[13px] font-semibold text-slate-800 dark:text-slate-200 focus-visible:outline-none" data-nav="' + esc(paper.nav) + '" ' + (cur.page === 'paper' && curNav === paper.nav ? 'aria-current="page"' : '') + '>' + esc(paper.title) + '</a>' +
        '<span class="text-[10px] font-bold ' + (pr.pct === 100 ? 'text-emerald-500' : 'text-indigo-600 dark:text-indigo-400') + '">' + pr.pct + '%</span></div>';
      html += '<div id="paper-' + esc(paper.id) + '" class="ml-3 border-l border-slate-200 dark:border-slate-700 pl-1 ' + (open ? '' : 'hidden') + '" role="group">';
      html += renderTreeLevel(paper.sub || [], 0, curNav, cur.page);
      html += '</div></div>';
    });
    html += '</nav>';

    /* Content library (files) */
    html += '<div class="border-t border-slate-200 dark:border-slate-700 px-4 py-2">' +
      '<div class="text-[11px] font-bold uppercase tracking-wider text-slate-400 mb-1">Content Library</div>' +
      '<div id="file-tree" class="text-[12px]"></div></div>';
    html += '<nav class="border-t border-slate-200 dark:border-slate-700 p-3 text-[11px] text-slate-500 dark:text-slate-400 space-y-1" aria-label="Utility navigation">' +
      '<a class="block hover:text-indigo-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded px-1 -mx-1 ' + (cur.page === 'tracker' ? 'text-indigo-600 dark:text-indigo-400 font-semibold' : '') + '" href="#/tracker" ' + (cur.page === 'tracker' ? 'aria-current="page"' : '') + '>✅ Revision Tracker</a>' +
      '<a class="block hover:text-indigo-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded px-1 -mx-1 ' + (cur.page === 'search' ? 'text-indigo-600 dark:text-indigo-400 font-semibold' : '') + '" href="#/search" ' + (cur.page === 'search' ? 'aria-current="page"' : '') + '>🔍 Global Search</a>' +
      '<a class="block hover:text-indigo-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded px-1 -mx-1" href="content/index.html" target="_blank" rel="noopener">📁 All HTML files (direct list)</a>' +
      '<a class="block hover:text-indigo-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded px-1 -mx-1" target="_blank" rel="noopener" href="https://github.com/clickalex/studyUPSC">GitHub repo ↗</a></nav>';

    box.innerHTML = html;
    renderFileTree();
  }

  function renderTreeLevel(nodes, depth, curNav, curPage) {
    curNav = curNav || '';
    curPage = curPage || '';
    var html = '';
    nodes.forEach(function (n) {
      var isL = isLeaf(n);
      var pr = nodeProgress(n);
      var open = expanded['n:' + n.nav];
      // Auto-open ancestors of current route
      if (curNav && (curNav === n.nav || curNav.indexOf(n.nav + '/') === 0)) open = true;
      var href = isL ? navHref('topic', n.nav) : navHref('paper', n.nav);
      var isActive = curNav === n.nav;
      var isAncestor = !isActive && curNav.indexOf(n.nav + '/') === 0;
      html += '<div class="mt-0.5" role="treeitem" aria-expanded="' + (isL ? 'false' : (open ? 'true' : 'false')) + '">';
      if (isL) {
        html += '<div class="flex items-center gap-1 rounded px-1.5 py-1 hover:bg-slate-100 dark:hover:bg-slate-800 group ' + (isActive ? 'nav-active' : '') + (isAncestor ? ' bg-indigo-50/40 dark:bg-indigo-950/20' : '') + '">' +
          numBadge(n.nav, true) +
          '<a href="' + href + '" class="flex-1 truncate text-slate-600 dark:text-slate-300 hover:text-indigo-600 dark:hover:text-indigo-400 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded" title="' + esc(n.title) + '" data-nav="' + esc(n.nav) + '" ' + (isActive ? 'aria-current="page"' : '') + '>' + esc(n.title) + '</a>' +
          '<span class="opacity-0 group-hover:opacity-100 transition-opacity" title="Mark topic done">' + leafCheckbox(n.nav) + '</span></div>';
      } else {
        html += '<div class="flex items-center gap-1 rounded px-1.5 py-1 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer ' + (isActive ? 'nav-active' : '') + (isAncestor ? ' bg-indigo-50/30 dark:bg-indigo-950/15' : '') + '" data-expand="n:' + n.nav + '" role="button" tabindex="0" aria-expanded="' + (open ? 'true' : 'false') + '">' +
          '<span class="chev ' + (open ? 'rotate-90' : '') + '" aria-hidden="true">' + treeIcon(n) + '</span>' +
          numBadge(n.nav, true) +
          '<a href="' + href + '" class="flex-1 truncate text-slate-600 dark:text-slate-300 hover:text-indigo-600 dark:hover:text-indigo-400 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-indigo-500 rounded" title="' + esc(n.title) + '" data-nav="' + esc(n.nav) + '" ' + (isActive && curPage === 'paper' ? 'aria-current="page"' : '') + '>' + esc(n.title) + '</a>' +
          '<span class="text-[10px] font-semibold ' + (pr.pct === 100 ? 'text-emerald-500' : 'text-slate-400') + '">' + pr.pct + '%</span></div>';
        html += '<div class="ml-2 border-l border-slate-200 dark:border-slate-700 pl-1 ' + (open ? '' : 'hidden') + '" role="group">' + renderTreeLevel(n.sub, depth + 1, curNav, curPage) + '</div>';
      }
      html += '</div>';
    });
    return html;
  }

  function renderFileTree() {
    var box = $('#file-tree');
    if (!box) return;
    var top = { 'content/prelims': [], 'content/mains': [] };
    DIRS.forEach(function (d) {
      if (d.dir.indexOf('content/prelims/') === 0) top['content/prelims'].push(d);
      else if (d.dir.indexOf('content/mains/') === 0) top['content/mains'].push(d);
    });
    function level(dirName, dirs, depth) {
      var html = '';
      dirs.forEach(function (d) {
        var label = d.dir.split('/').pop();
        var open = expanded['d:' + d.dir];
        var children = dirs.filter(function (x) { return x.dir.indexOf(d.dir + '/') === 0 && x.dir.slice(d.dir.length + 1).indexOf('/') === -1; });
        var hasKids = children.length > 0;
        html += '<div class="mt-0.5">';
        if (hasKids) {
          html += '<div class="flex items-center gap-1 rounded px-1 py-0.5 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer" data-expand="d:' + d.dir + '">' +
            '<span class="chev ' + (open ? 'rotate-90' : '') + ' w-3 text-slate-400">▶</span>' +
            '<span class="flex-1 truncate text-slate-500 dark:text-slate-400">📁 ' + esc(label) + '</span>' +
            '<span class="text-[10px] text-slate-400">' + d.files.length + '</span></div>';
          html += '<div class="ml-2 border-l border-slate-200 dark:border-slate-700 pl-1 ' + (open ? '' : 'hidden') + '">' + level(d.dir, children, depth + 1) + '</div>';
        } else {
          html += '<a href="#/doc/' + encodeURIComponent((d.files[0] || {}).rel || '') + '" class="flex items-center gap-1 rounded px-1 py-0.5 text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400" title="' + esc(d.dir) + '">' +
            '<span class="w-3 text-slate-400">·</span><span class="flex-1 truncate">📄 ' + esc(label) + '</span><span class="text-[10px]">' + d.files.length + '</span></a>';
        }
        html += '</div>';
      });
      return html;
    }
    var html = '';
    ['content/prelims', 'content/mains'].forEach(function (t) {
      var dirs = top[t];
      if (!dirs.length) return;
      var open = expanded['d:' + t];
      html += '<div class="mt-1">';
      html += '<div class="flex items-center gap-1 rounded px-1 py-0.5 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer" data-expand="d:' + t + '">' +
        '<span class="chev ' + (open ? 'rotate-90' : '') + ' w-3 text-slate-400">▶</span>' +
        '<span class="flex-1 truncate font-semibold text-slate-600 dark:text-slate-300">' + (t === 'content/prelims' ? 'Prelims' : 'Mains') + '</span></div>';
      html += '<div class="ml-2 border-l border-slate-200 dark:border-slate-700 pl-1 ' + (open ? '' : 'hidden') + '">' + level(t, dirs, 1) + '</div>';
      html += '</div>';
    });
    box.innerHTML = html;
  }

  /* ------------------------------------------------------------------ */
  /*  Layout shell                                                        */
  /* ------------------------------------------------------------------ */
  function shell(contentHtml, opts) {
    opts = opts || {};
    var crumbs = opts.crumbs || [];
    var crumbHtml = '<nav class="flex items-center gap-1.5 text-[12px] text-slate-500 dark:text-slate-400 flex-wrap" aria-label="Breadcrumb">' +
      '<a href="#/" class="hover:text-indigo-500 font-semibold focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded">⌂ Home</a>';
    crumbs.forEach(function (c, i) {
      var isLast = i === crumbs.length - 1;
      var href = c.nav ? navHref(c.page || 'topic', c.nav) : '#/';
      crumbHtml += '<span class="text-slate-300 dark:text-slate-600" aria-hidden="true">›</span>' + (isLast
        ? '<span class="font-semibold text-slate-700 dark:text-slate-200" aria-current="page">' + esc(c.title) + '</span>'
        : '<a href="' + href + '" class="hover:text-indigo-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 rounded">' + esc(c.title) + '</a>');
    });
    crumbHtml += '</nav>';
    return '<div class="max-w-6xl mx-auto px-4 sm:px-6 py-7">' +
      '<div class="mb-6 flex items-center justify-between gap-3 flex-wrap">' + crumbHtml +
      '<div class="flex items-center gap-2">' +
      '<button class="btn-ghost text-[12px]" onclick="window.location.hash=\'#/tracker\'">✅ Tracker</button>' +
      '<button class="btn-ghost text-[12px]" onclick="openSearch()">🔍 Search <kbd class="hidden sm:inline kbd">Ctrl K</kbd></button></div></div>' +
      contentHtml + '</div>';
  }

  /* ------------------------------------------------------------------ */
  /*  Home dashboard                                                      */
  /* ------------------------------------------------------------------ */
  function renderHome() {
    var o = overallProgress();
    var html = '';
    var circ = 2 * Math.PI * 42;
    html += '<div class="hero-shell relative overflow-hidden rounded-3xl bg-gradient-to-br from-indigo-950 via-slate-900 to-slate-900 text-white p-8 sm:p-10 mb-8 shadow-lift">' +
      '<div class="hero-grid"></div>' +
      '<div class="relative z-10 flex flex-wrap items-center gap-8">' +
      '<div class="max-w-2xl flex-1 min-w-[260px]">' +
      '<p class="text-amber-400 text-[11px] font-bold uppercase tracking-[0.22em] mb-3">Civil Services Examination · IAS · IPS · IFS</p>' +
      '<h1 class="font-display text-3xl sm:text-[2.6rem] font-extrabold leading-[1.15] mb-4">Your complete UPSC CSE<br><span class="gradient-text">syllabus command centre</span></h1>' +
      '<p class="text-slate-300 text-sm sm:text-base mb-6 leading-relaxed">Prelims &amp; Mains syllabus mapped into detailed notes, revision sheets, mindmaps, diagrams and PYQs — with a built-in completion tracker and instant full-text search.</p>' +
      '<div class="flex flex-wrap gap-3">' +
      '<button class="btn-primary" onclick="document.getElementById(\'stage-prelims\').scrollIntoView({behavior:\'smooth\'})">Start with Prelims</button>' +
      '<button class="btn-ghost-light" onclick="openSearch()">Search everything 🔍</button>' +
      '<a class="btn-ghost-light" href="book/index.html">Read as a book 📖</a></div></div>' +
      '<div class="hidden md:flex flex-col items-center gap-2 px-6 py-5 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-sm">' +
      '<div class="relative w-28 h-28">' +
      '<svg viewBox="0 0 100 100" class="w-28 h-28 -rotate-90"><circle cx="50" cy="50" r="42" fill="none" stroke="rgba(255,255,255,.12)" stroke-width="9"/>' +
      '<circle cx="50" cy="50" r="42" fill="none" stroke="#818cf8" stroke-width="9" stroke-linecap="round" stroke-dasharray="' + circ + '" stroke-dashoffset="' + (circ * (1 - o.pct / 100)) + '"/></svg>' +
      '<div class="absolute inset-0 flex flex-col items-center justify-center"><span class="font-display text-2xl font-extrabold">' + o.pct + '%</span>' +
      '<span class="text-[9px] uppercase tracking-[0.18em] text-slate-400">done</span></div></div>' +
      '<div class="text-[11px] text-slate-400">' + o.done + '/' + o.total + ' topics</div></div></div></div>';

    /* ---- continue learning (shared with the static site) ---- */
    var last = getLastVisit();
    if (last && (last.hash || last.rel || last.nav)) {
      var resumeHref = last.hash || last.rel || '#/';
      if (last.hash && last.hash.charAt(0) === '#') resumeHref = last.hash;
      html += '<a href="' + esc(resumeHref) + '" class="group flex items-center gap-3 rounded-2xl border border-indigo-200 dark:border-indigo-800 bg-gradient-to-r from-indigo-50 to-white dark:from-indigo-950/50 dark:to-slate-900 px-5 py-3.5 mb-6 shadow-card hover:shadow-lift hover:-translate-y-0.5 transition-all">' +
        '<span class="text-[11px] font-extrabold uppercase tracking-[0.14em] text-indigo-600 dark:text-indigo-300">▶ Continue</span>' +
        '<span class="font-semibold text-slate-800 dark:text-slate-100 truncate">' + esc(last.title || 'your last topic') + '</span>' +
        '<span class="ml-auto text-indigo-500 font-bold group-hover:translate-x-1 transition-transform">Resume →</span></a>';
    }

    /* ---- start-here path: the whole exam in 4 ordered steps ---- */
    html += '<div class="card p-5 sm:p-6 mb-6 shadow-card">' +
      '<h2 class="font-display text-lg font-bold mb-1">🗺️ New here? Follow the path in order</h2>' +
      '<p class="text-[13px] text-slate-500 dark:text-slate-400 mb-4">Four steps, top-to-bottom — the numbers below match the sidebar, the library and the book.</p>' +
      '<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-3">' +
      '<a href="#/paper/prelims-gs1" class="rounded-2xl border border-slate-200 dark:border-slate-800 p-4 hover:border-indigo-400 dark:hover:border-indigo-500 hover:-translate-y-0.5 transition-all"><span class="su-step">Step 1</span><b class="block text-sm mt-2 mb-1">🧭 Understand the exam</b><span class="block text-[12px] text-slate-500 dark:text-slate-400">Papers, marks, what counts. Prelims screens, Mains ranks.</span></a>' +
      '<a href="#stage-prelims" data-scrollto="stage-prelims" class="rounded-2xl border border-slate-200 dark:border-slate-800 p-4 hover:border-indigo-400 dark:hover:border-indigo-500 hover:-translate-y-0.5 transition-all"><span class="su-step">Step 2</span><b class="block text-sm mt-2 mb-1">📋 Finish Prelims (1 → 3)</b><span class="block text-[12px] text-slate-500 dark:text-slate-400">GS Paper I in order, then CSAT, then timed mocks.</span></a>' +
      '<a href="#stage-mains" data-scrollto="stage-mains" class="rounded-2xl border border-slate-200 dark:border-slate-800 p-4 hover:border-indigo-400 dark:hover:border-indigo-500 hover:-translate-y-0.5 transition-all"><span class="su-step">Step 3</span><b class="block text-sm mt-2 mb-1">✍️ Finish Mains (4 → 10)</b><span class="block text-[12px] text-slate-500 dark:text-slate-400">GS I–IV + Essay first, then your ONE optional.</span></a>' +
      '<a href="#/tracker" class="rounded-2xl border border-slate-200 dark:border-slate-800 p-4 hover:border-indigo-400 dark:hover:border-indigo-500 hover:-translate-y-0.5 transition-all"><span class="su-step">Step 4</span><b class="block text-sm mt-2 mb-1">✅ Track &amp; test</b><span class="block text-[12px] text-slate-500 dark:text-slate-400">Tick topics done, quiz yourself on PYQs.</span></a>' +
      '</div></div>';

    /* ---- book promo ---- */
    var BK = window.BOOK_DATA;
    if (BK) {
      html += '<a href="book/index.html" class="block group mb-10 rounded-3xl overflow-hidden border border-amber-200 dark:border-amber-900/40 bg-gradient-to-r from-amber-50 to-white dark:from-slate-900 dark:to-slate-900 shadow-card hover:shadow-lift transition-shadow">' +
        '<div class="flex flex-col sm:flex-row items-stretch">' +
        '<img src="assets/book/img/cover.png" alt="" class="w-full sm:w-40 h-40 sm:h-auto object-cover">' +
        '<div class="p-6 flex-1">' +
        '<p class="text-[11px] font-bold uppercase tracking-[0.2em] text-amber-600 dark:text-amber-400 mb-1">Complete edition</p>' +
        '<h3 class="font-display text-xl font-extrabold mb-1 group-hover:text-amber-600 transition-colors">' + esc(BK.title) + '</h3>' +
        '<p class="text-sm text-slate-500 dark:text-slate-400 mb-3 max-w-xl">Every part, chapter and lesson of the syllabus woven into one continuous read — detailed study, revision digest, mindmaps, diagrams and PYQs in each lesson.</p>' +
        '<div class="flex flex-wrap gap-5 text-[12px] font-semibold text-slate-600 dark:text-slate-300">' +
        '<span><b class="text-amber-600 dark:text-amber-400">' + BK.parts.length + '</b> parts</span>' +
        '<span><b class="text-amber-600 dark:text-amber-400">' + BK.chapters + '</b> chapters</span>' +
        '<span><b class="text-amber-600 dark:text-amber-400">' + BK.lessons + '</b> lessons</span>' +
        '<span><b class="text-amber-600 dark:text-amber-400">~' + BK.pages + '</b> pages</span></div>' +
        '</div></div></a>';
    }

    var prelimsPapers = DATA.papers.filter(function (p) { return p.stage === 'prelims'; });
    var mainsPapers = DATA.papers.filter(function (p) { return p.stage === 'mains'; });
    var docCount = INDEX.filter(function (f) { return f.kind === 'doc'; }).length;

    html += '<div class="grid grid-cols-2 md:grid-cols-4 gap-3 mb-10">' +
      statCard('📋', String(prelimsPapers.length), 'Prelims sections', 'GS I · CSAT · Mocks') +
      statCard('✍️', String(mainsPapers.length), 'Mains sections', 'GS 1–4 · Essay · Optional') +
      statCard('🗂️', String(docCount || DIRS.length), docCount ? 'Notes & question sets' : 'Content folders', 'every topic covered') +
      statCard('🎯', o.pct + '%', 'Syllabus done', o.done + '/' + o.total + ' topics') +
      '</div>';

    html += stageBlock('stage-prelims', '📋', 'Preliminary Examination', 'Objective · 2 papers · qualifying CSAT', prelimsPapers);
    html += stageBlock('stage-mains', '✍️', 'Main Examination', 'Conventional · 9 papers · 1750 marks', mainsPapers);

    html += '<div class="grid lg:grid-cols-3 gap-6 mt-10">';
    html += '<div class="card lg:col-span-2 p-6 shadow-card">' +
      '<h2 class="font-display text-lg font-bold mb-1">🗂️ How this portal is organised</h2>' +
      '<p class="text-sm text-slate-500 dark:text-slate-400 mb-4">Every syllabus topic branches into five content sections — complete coverage across the whole exam.</p>' +
      '<div class="grid sm:grid-cols-5 gap-2.5">' + SECTIONS.map(function (s) {
        return '<div class="rounded-2xl border border-slate-200 dark:border-slate-800 bg-slate-50/60 dark:bg-slate-900/60 p-3.5 text-center hover:border-indigo-400 dark:hover:border-indigo-500 hover:-translate-y-0.5 transition-all"><div class="text-2xl mb-1.5">' + s.icon + '</div><div class="text-[11px] font-semibold text-slate-700 dark:text-slate-200 leading-tight">' + esc(s.title) + '</div></div>';
      }).join('') + '</div></div>';

    html += '<div class="card p-6 shadow-card">' +
      '<h2 class="font-display text-lg font-bold mb-3">🏃 Quick start</h2>' +
      '<ol class="text-sm text-slate-600 dark:text-slate-300 space-y-2.5 list-decimal list-inside">' +
      '<li>Browse the syllabus tree on the left</li>' +
      '<li>Tick topics you finish — progress saves automatically</li>' +
      '<li>Press <kbd class="kbd">Ctrl</kbd>+<kbd class="kbd">K</kbd> to search anywhere</li>' +
      '<li>Take the mock tests in the Prelims → Mocks section</li>' +
      '<li>Watch your tracker ring fill up</li></ol>' +
      '<div class="mt-5 pt-4 border-t border-slate-200 dark:border-slate-800"><a href="#/tracker" class="btn-primary w-full justify-center">Open Revision Tracker</a></div>' +
      '<a href="content/index.html" target="_blank" rel="noopener" class="mt-2.5 btn-ghost w-full justify-center">📁 Open every HTML file directly</a></div>';
    html += '</div>';
    $('#app').innerHTML = shell(html);
  }

  function statCard(icon, big, label, sub) {
    return '<div class="card p-4 shadow-card hover:-translate-y-0.5 transition-transform">' +
      '<div class="w-9 h-9 rounded-xl bg-indigo-50 dark:bg-indigo-950/60 flex items-center justify-center text-lg mb-2.5">' + icon + '</div>' +
      '<div class="font-display text-2xl font-extrabold text-slate-900 dark:text-white">' + big + '</div>' +
      '<div class="text-[12px] font-semibold text-slate-600 dark:text-slate-300">' + label + '</div>' +
      '<div class="text-[11px] text-slate-400">' + sub + '</div></div>';
  }

  function stageBlock(id, icon, title, subtitle, papers) {
    var html = '<div id="' + id + '" class="mb-8">';
    html += '<div class="flex items-end justify-between mb-4">' +
      '<div><h2 class="font-display text-xl font-extrabold text-slate-900 dark:text-white">' + icon + ' ' + title + '</h2>' +
      '<p class="text-sm text-slate-500 dark:text-slate-400">' + subtitle + '</p></div></div>';
    html += '<div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">';
    papers.forEach(function (p) {
      var pr = paperProgress(p);
      var topicCount = (function count(n) { return (n.sub || []).reduce(function (a, c) { return a + count(c); }, isLeaf(n) ? 1 : 0); })(p);
      html += '<a href="#/paper/' + encodeURIComponent(p.nav) + '" class="group card p-5 shadow-card hover:border-indigo-400 dark:hover:border-indigo-500 hover:shadow-lift hover:-translate-y-0.5 transition-all">' +
        '<div class="flex items-start justify-between gap-2">' +
        '<div><div class="chip bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-300 mb-1.5">' + esc(p.tag || p.stage) + '</div>' +
        '<h3 class="font-display font-bold text-slate-900 dark:text-white group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">' + numBadge(p.nav) + ' ' + esc(p.title) + '</h3></div>' +
        '<span class="text-indigo-400 opacity-0 group-hover:opacity-100 transition-all group-hover:translate-x-0.5">→</span></div>' +
        '<p class="text-[13px] text-slate-500 dark:text-slate-400 mt-2 line-clamp-2">' + esc(p.summary || '') + '</p>' +
        '<div class="mt-4 flex items-center gap-2.5">' + progressBar(pr.pct, pr.pct === 100 ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-violet-500') +
        '<span class="text-[11px] font-bold text-slate-500 dark:text-slate-400 whitespace-nowrap">' + pr.pct + '% · ' + topicCount + ' topics</span></div></a>';
    });
    html += '</div></div>';
    return html;
  }

  /* ------------------------------------------------------------------ */
  /*  Paper (subject) page                                                */
  /* ------------------------------------------------------------------ */
  function filesUnder(navPrefix) {
    return INDEX.filter(function (f) {
      return f.nav === navPrefix || f.nav.indexOf(navPrefix + '/') === 0;
    });
  }
  function dirsUnder(navPrefix) {
    return DIRS.filter(function (d) {
      return d.nav === navPrefix || d.nav.indexOf(navPrefix + '/') === 0;
    });
  }

  function renderPaper(nav) {
    nav = normalizeNav(nav);
    var node = NODE_BY_NAV[nav];
    if (!node) { renderNotFound(nav); return; }
    // If leaf was requested via /paper, render as topic view for correctness
    if (isLeaf(node)) { renderTopic(nav); return; }
    recordVisit({ kind: 'app', nav: node.nav, title: node.title, hash: '#/paper/' + encodeURIComponent(node.nav) });
    var pr = nodeProgress(node);
    var crumbs = crumbsFor(nav).map(function (c) { return { page: c.nav === node.nav ? 'paper' : 'topic', nav: c.nav, title: c.title }; });
    if (node.stage) crumbs = [];
    crumbs = crumbs.concat({ page: 'paper', nav: node.nav, title: node.title });

    var files = filesUnder(node.nav);
    var html = '';
    html += '<div class="relative overflow-hidden card p-6 mb-6 shadow-card">' +
      '<div class="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-indigo-500 via-violet-500 to-amber-400"></div>';
    html += '<div class="chip bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-300 mb-2">' + esc(node.tag || (node.stage === 'prelims' ? 'Prelims' : 'Mains')) + '</div>';
    html += '<h1 class="font-display text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white">' + numBadge(node.nav) + ' ' + esc(node.title) + '</h1>';
    if (node.full) html += '<p class="text-sm font-medium text-slate-500 dark:text-slate-400 mt-1">' + esc(node.full) + '</p>';
    if (node.summary) html += '<p class="text-sm text-slate-600 dark:text-slate-300 mt-3 max-w-3xl leading-relaxed">' + esc(node.summary) + '</p>';
    html += '<div class="mt-5 flex items-center gap-3 flex-wrap"><div class="w-44">' + progressBar(pr.pct, pr.pct === 100 ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-violet-500') + '</div>' +
      '<span class="text-sm font-bold ' + (pr.pct === 100 ? 'text-emerald-500' : 'text-slate-700 dark:text-slate-200') + '">' + pr.pct + '% complete</span>' +
      '<span class="text-xs text-slate-400">' + pr.done + '/' + pr.total + ' topics done</span></div></div>';

    /* exam pattern for the two main stages */
    var stageKey = node.stage === 'prelims' ? 'prelims' : (node.id === 'gs-1' || node.id === 'gs-2' || node.id === 'gs-3' || node.id === 'gs-4' || node.id === 'essay' ? 'mains' : null);
    if (stageKey) {
      var ex = DATA.exam[stageKey];
      html += '<div class="card p-6 mb-6 shadow-card overflow-hidden">' +
        '<h2 class="font-display text-lg font-bold mb-4">📐 ' + esc(ex.title) + ' — pattern</h2>' +
        '<div class="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-800"><table class="w-full text-sm"><thead><tr class="text-left text-[11px] uppercase tracking-wider text-slate-400 bg-slate-50 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800">' +
        '<th class="py-2.5 px-4 font-bold">Paper</th><th class="py-2.5 px-3 font-bold">Marks</th><th class="py-2.5 px-3 font-bold">Duration</th><th class="py-2.5 px-3 font-bold">Note</th></tr></thead><tbody>';
      ex.pattern.forEach(function (r) {
        html += '<tr class="border-b border-slate-100 dark:border-slate-800 last:border-0 hover:bg-indigo-50/40 dark:hover:bg-indigo-950/30 transition-colors"><td class="py-2.5 px-4 font-semibold text-slate-700 dark:text-slate-200">' + esc(r.paper) + '</td>' +
          '<td class="py-2.5 px-3">' + esc(r.marks) + '</td><td class="py-2.5 px-3">' + esc(r.time || '—') + '</td><td class="py-2.5 px-3 text-slate-500 dark:text-slate-400">' + esc(r.note || '') + '</td></tr>';
      });
      html += '</tbody></table></div></div>';
    }

    /* topics */
    html += '<h2 class="font-display text-lg font-bold mb-3">🧭 Topics in this paper</h2>';
    if (node.sub && node.sub.length) {
      html += '<div class="grid sm:grid-cols-2 gap-3 mb-6">';
      node.sub.forEach(function (t) {
        var tp = nodeProgress(t);
        var isL = isLeaf(t);
        var done = tp.pct === 100;
        html += '<a href="#/' + (isL ? 'topic' : 'paper') + '/' + encodeURIComponent(t.nav) + '" class="group card p-4 hover:border-indigo-400 dark:hover:border-indigo-500 hover:shadow-lift hover:-translate-y-0.5 transition-all">' +
          '<div class="flex items-center justify-between gap-2">' +
          '<div class="font-semibold text-slate-800 dark:text-slate-100 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">' + numBadge(t.nav, true) + ' ' + esc(t.title) + '</div>' +
          (isL ? leafCheckbox(t.nav) : '<span class="text-[10px] font-bold ' + (done ? 'text-emerald-500' : 'text-indigo-500 dark:text-indigo-400') + '">' + tp.pct + '%</span>') + '</div>' +
          (t.tag ? '<div class="text-[11px] text-slate-400 mt-1">' + esc(t.tag) + '</div>' : '') +
          (isL ? '<div class="mt-2.5">' + progressBar(tp.pct, done ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-violet-500') + '</div>' : '') +
          (t.sub ? '<div class="mt-2 text-[11px] text-slate-400">' + t.sub.length + ' sub-topics</div>' : '') + '</a>';
      });
      html += '</div>';
    }

    /* files */
    var dirs = dirsUnder(node.nav);
    if (files.length) {
      html += '<h2 class="text-lg font-bold mb-3">📁 Study material (' + files.length + ' files)</h2>';
      html += renderFileGroups(node.nav, dirs, files);
    } else {
      html += '<div class="rounded-2xl border border-dashed border-slate-300 dark:border-slate-600 p-6 text-center text-sm text-slate-500 dark:text-slate-400 mb-6">' +
        'No study material yet — drop HTML pages, images or PDFs into <code class="code">upsc-portal/content/</code>, ' +
        'then run <code class="code">node cli/generate.mjs</code>.<br>' +
        '<a class="text-indigo-600 dark:text-indigo-400 font-semibold" href="#/tracker">→ Track this paper in the Revision Tracker</a></div>';
    }
    $('#app').innerHTML = shell(html, { crumbs: crumbs });
  }

  /* ------------------------------------------------------------------ */
  /*  Topic page                                                          */
  /* ------------------------------------------------------------------ */
  function renderTopic(nav, section) {
    nav = normalizeNav(nav);
    var node = NODE_BY_NAV[nav];
    if (!node) { renderNotFound(nav); return; }
    recordVisit({ kind: 'app', nav: node.nav, title: node.title, hash: '#/topic/' + encodeURIComponent(node.nav) });
    var pr = nodeProgress(node);
    var crumbs = crumbsFor(nav).map(function (c) {
      var isPaper = DATA.papers.some(function (p) { return p.nav === c.nav; });
      return { page: isPaper ? 'paper' : 'topic', nav: c.nav, title: c.title };
    });
    var files = filesUnder(node.nav);
    var html = '';

    var topicDone = progress[node.nav] === 1;
    html += '<div class="relative overflow-hidden card p-6 mb-6 shadow-card">' +
      '<div class="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-indigo-500 via-violet-500 to-amber-400"></div>' +
      '<div class="flex flex-wrap items-start justify-between gap-3">' +
      '<div><h1 class="font-display text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white">' + numBadge(node.nav) + ' ' + esc(node.title) + '</h1>' +
      (node.tag ? '<div class="chip bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-300 mt-2">' + esc(node.tag) + '</div>' : '') +
      (node.note ? '<p class="text-sm text-slate-500 dark:text-slate-400 mt-2">' + esc(node.note) + '</p>' : '') + '</div>' +
      '<div class="flex items-center gap-2">' +
      (isLeaf(node) ? leafCheckbox(node.nav) + '<span class="text-sm font-semibold ' + (topicDone ? 'text-emerald-500' : 'text-slate-600 dark:text-slate-300') + '">' + (topicDone ? 'Completed ✅' : 'Mark complete') + '</span>'
        : '<span class="text-sm font-bold text-indigo-600 dark:text-indigo-400">' + pr.pct + '%</span>') + '</div></div>' +
      '<div class="mt-4"><div class="w-full max-w-md">' + progressBar(pr.pct, pr.pct === 100 || topicDone ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-violet-500') + '</div></div></div>';

    if (node.sub && node.sub.length) {
      html += '<h2 class="font-display text-lg font-bold mb-3">Sub-topics</h2><div class="grid sm:grid-cols-2 gap-3 mb-6">';
      node.sub.forEach(function (t) {
        var tp = nodeProgress(t);
        var tDone = tp.pct === 100;
        html += '<a href="#/topic/' + encodeURIComponent(t.nav) + '" class="card p-4 hover:border-indigo-400 dark:hover:border-indigo-500 hover:shadow-lift hover:-translate-y-0.5 transition-all flex items-center justify-between gap-2 group">' +
          '<span class="font-semibold text-slate-800 dark:text-slate-100 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">' + numBadge(t.nav, true) + ' ' + esc(t.title) + '</span>' +
          (isLeaf(t) ? leafCheckbox(t.nav) : '<span class="text-[10px] font-bold ' + (tDone ? 'text-emerald-500' : 'text-indigo-500') + '">' + tp.pct + '%</span>') + '</a>';
      });
      html += '</div>';
    }

    /* the five canonical sections */
    html += '<h2 class="font-display text-lg font-bold mb-3">📂 Study sections</h2>';
    html += '<div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-3 mb-6">';
    SECTIONS.forEach(function (s) {
      var secNav = node.nav + '/' + s.id;
      var secDirs = dirsUnder(secNav);
      var secFiles = filesUnder(secNav);
      var count = secFiles.length;
      html += '<a href="#/topic/' + encodeURIComponent(node.nav) + '/section/' + s.id + '" data-section="' + s.id + '" class="section-card card p-5 shadow-card hover:border-indigo-400 dark:hover:border-indigo-500 hover:shadow-lift hover:-translate-y-0.5 transition-all cursor-pointer">' +
        '<div class="flex items-center justify-between mb-3"><span class="w-11 h-11 rounded-xl bg-indigo-50 dark:bg-indigo-950/60 flex items-center justify-center text-2xl">' + s.icon + '</span>' +
        (count ? '<span class="chip bg-emerald-50 dark:bg-emerald-950/50 text-emerald-600 dark:text-emerald-300">' + count + ' file' + (count > 1 ? 's' : '') + '</span>' : '') + '</div>' +
        '<h3 class="font-display font-bold text-slate-900 dark:text-white text-sm leading-snug">' + esc(s.title) + '</h3>' +
        '<p class="text-[12px] text-slate-500 dark:text-slate-400 mt-1">' + esc(s.desc) + '</p>' +
        '<div class="mt-2.5 text-[11px] text-slate-400 font-mono">' + (secDirs.length ? 'content/' + esc(secDirs[0].dir.replace('content/', '')) : 'folder ready for you') + '</div></a>';
    });
    html += '</div>';

    /* files in the topic */
    if (files.length) {
      html += '<h2 class="text-lg font-bold mb-3">📄 Files in this topic (' + files.length + ')</h2>';
      html += renderFileGroups(node.nav, dirsUnder(node.nav), files);
    }

    /* ordered up-next: walk the syllabus leaf by leaf, in study order */
    html += upNextHtml(node.nav);

    $('#app').innerHTML = shell(html, { crumbs: crumbs });
    $('.section-card').forEach(function (el) {
      el.addEventListener('click', function (e) { e.preventDefault(); openSection(node, el.dataset.section); });
    });
    if (section) {
      // Defer to allow DOM paint
      setTimeout(function(){ openSection(node, section); }, 50);
    }
  }

  /* Ordered prev/next across the whole syllabus (leaf topics in study order). */
  function upNextHtml(nav) {
    var i = leafIndex(nav);
    if (i < 0) return '';
    var prev = i > 0 ? LEAVES[i - 1] : null;
    var next = i < LEAVES.length - 1 ? LEAVES[i + 1] : null;
    function cut(t) { t = String(t); return t.length > 44 ? t.slice(0, 43) + '…' : t; }
    var html = '<div class="card p-5 mt-6 shadow-card">' +
      '<div class="text-[10.5px] font-bold uppercase tracking-[0.14em] text-slate-400 mb-3">📍 Study in order · topic ' + (i + 1) + ' of ' + LEAVES.length + '</div>' +
      '<div class="flex flex-wrap items-center gap-2.5">' +
      (prev ? '<a href="#/topic/' + encodeURIComponent(prev.nav) + '" class="btn-ghost text-[12px]">← ' + numBadge(prev.nav, true) + ' ' + esc(cut(prev.title)) + '</a>' : '<span></span>') +
      '<span class="flex-1"></span>' +
      (next
        ? '<button class="btn-primary text-[12px]" data-done-next="' + esc(nav) + '">' + (progress[nav] === 1 ? 'Next topic →' : '✓ Mark done &amp; continue →') + '</button>'
        : '<a href="#/tracker" class="btn-primary text-[12px]">Finish → tracker ✅</a>') +
      '</div>' +
      (next ? '<div class="mt-2.5 text-[12px] text-slate-500 dark:text-slate-400">Up next: ' + numBadge(next.nav, true) + ' <a class="font-semibold text-indigo-600 dark:text-indigo-400 hover:underline" href="#/topic/' + encodeURIComponent(next.nav) + '">' + esc(next.title) + '</a></div>' : '') +
      '</div>';
    return html;
  }

  /* open a section panel (modal listing that section's files) */
  function openSection(node, sectionId) {
    var sec = sectionMeta(sectionId);
    var secNav = node.nav + '/' + sectionId;
    var files = filesUnder(secNav);
    var html = '<div class="fixed inset-0 z-50 flex items-start justify-center p-4 sm:p-8" role="dialog" aria-modal="true">' +
      '<div class="absolute inset-0 bg-slate-950/60 backdrop-blur-sm" data-close></div>' +
      '<div class="relative w-full max-w-2xl rounded-3xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xl max-h-[85vh] flex flex-col overflow-hidden">' +
      '<div class="relative flex items-start justify-between p-5 border-b border-slate-200 dark:border-slate-800">' +
      '<div class="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-indigo-500 via-violet-500 to-amber-400"></div>' +
      '<div class="flex items-center gap-3"><span class="w-11 h-11 rounded-xl bg-indigo-50 dark:bg-indigo-950/60 flex items-center justify-center text-2xl">' + (sec ? sec.icon : '📂') + '</span>' +
      '<div><h2 class="font-display text-lg font-bold text-slate-900 dark:text-white leading-tight">' + esc(node.title) + '</h2>' +
      '<p class="text-[12px] text-slate-500 dark:text-slate-400">' + esc(sec ? sec.title : humanTitle(sectionId)) + ' — ' + files.length + ' file' + (files.length === 1 ? '' : 's') + '</p></div></div>' +
      '<button class="btn-ghost" data-close>✕</button></div>' +
      '<div class="overflow-y-auto p-5">' +
      (files.length ? fileListHtml(files) :
        '<div class="text-center text-sm text-slate-500 dark:text-slate-400 py-10">Nothing here yet.<br>Add files to <code class="code">' + esc('content/' + secNav) + '/</code> and run the generator.</div>') +
      '</div></div></div>';
    var wrap = document.createElement('div');
    wrap.innerHTML = html;
    document.body.appendChild(wrap);
    function close() { wrap.remove(); }
    $$('[data-close]', wrap).forEach(function (el) { el.addEventListener('click', close); });
    wrap.addEventListener('click', function (e) { if (e.target === wrap) close(); });
  }

  /* Direct link to the original file (opens in a new tab, outside the SPA) */
  function openRaw(rel, label) {
    return '<a href="' + esc(rel) + '" target="_blank" rel="noopener" class="btn-ghost text-[12px] shrink-0" title="Open the original file directly in a new tab" aria-label="Open ' + esc(rel.split('/').pop()) + ' directly in a new tab">' + (label || 'Open file') + ' ↗</a>';
  }

  function fileListHtml(files) {
    return '<ul class="divide-y divide-slate-100 dark:divide-slate-700">' + files.map(function (f) {
      var icon = f.kind === 'image' ? '🖼️' : f.kind === 'pdf' ? '📕' : '📄';
      return '<li class="flex items-center gap-1 group">' +
        '<a href="#/doc/' + encodeURIComponent(f.rel) + '" class="flex items-center gap-3 py-2.5 flex-1 min-w-0 hover:bg-slate-50 dark:hover:bg-slate-700/40 rounded-lg px-2 -mx-1">' +
        '<span>' + icon + '</span><span class="flex-1 min-w-0"><span class="block truncate text-sm font-medium text-slate-700 dark:text-slate-200 group-hover:text-indigo-600 dark:group-hover:text-indigo-400">' + esc(f.file) + '</span>' +
        '<span class="block text-[11px] text-slate-400">' + esc(f.dir) + '</span></span>' +
        '<span class="text-[11px] text-slate-400 whitespace-nowrap">' + fmtBytes(f.size) + '</span></a>' +
        '<a href="' + esc(f.rel) + '" target="_blank" rel="noopener" title="Open this file directly in a new tab" aria-label="Open ' + esc(f.file) + ' directly in a new tab" class="shrink-0 px-2 py-1.5 rounded-lg text-slate-400 hover:text-indigo-500 dark:hover:text-indigo-400 hover:bg-slate-100 dark:hover:bg-slate-800 opacity-60 group-hover:opacity-100 transition-all">↗</a>' +
        '</li>';
    }).join('') + '</ul>';
  }

  function renderFileGroups(navPrefix, dirs, files) {
    /* group files by their immediate dir */
    var groups = {};
    files.forEach(function (f) { (groups[f.dir] = groups[f.dir] || []).push(f); });
    var dirNames = Object.keys(groups).sort();
    var html = '';
    dirNames.forEach(function (dir) {
      var label = dir.split('/').pop().replace(/-/g, ' ');
      var icon = SECTIONS.some(function (s) { return s.id === dir.split('/').pop(); }) ? '📂' : '🗂️';
      html += '<div class="mb-4 card shadow-card overflow-hidden">' +
        '<div class="px-4 py-2.5 bg-slate-50 dark:bg-slate-900/70 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between">' +
        '<span class="text-[12px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">' + icon + ' ' + esc(humanTitle(label)) + '</span>' +
        '<span class="text-[11px] text-slate-400">' + groups[dir].length + ' file' + (groups[dir].length > 1 ? 's' : '') + '</span></div>' +
        '<div class="p-2">' + fileListHtml(groups[dir]) + '</div></div>';
    });
    return html;
  }

  /* ------------------------------------------------------------------ */
  /*  Document viewer                                                     */
  /* ------------------------------------------------------------------ */
  function entryByRel(rel) {
    for (var i = 0; i < INDEX.length; i++) if (INDEX[i].rel === rel) return INDEX[i];
    return null;
  }

  function renderDoc(rel) {
    var entry = entryByRel(rel);
    if (!entry) { renderNotFound(rel, 'doc'); return; }
    recordVisit({ kind: 'app', nav: entry.nav, title: shortName(entry.file), hash: '#/doc/' + encodeURIComponent(rel), rel: rel });
    markReadRel(rel);
    var app = $('#app');
    app.innerHTML = shell('<div id="doc-body" class="animate-pulse"><div class="h-6 w-1/3 rounded bg-slate-200 dark:bg-slate-700 mb-3"></div><div class="h-3 w-full rounded bg-slate-100 dark:bg-slate-700 mb-2"></div><div class="h-3 w-5/6 rounded bg-slate-100 dark:bg-slate-700 mb-2"></div><div class="h-3 w-4/6 rounded bg-slate-100 dark:bg-slate-700"></div></div>',
      { crumbs: crumbsForNavFromRel(entry) });

    var icon = entry.kind === 'image' ? '🖼️' : entry.kind === 'pdf' ? '📕' : (entry.ext === 'html' ? '🌐' : '📄');
    if (entry.kind === 'image') {
      var imgSrc = rel;
      app.innerHTML = shell(
        '<div class="card shadow-card p-4">' +
        '<div class="flex items-center justify-between flex-wrap gap-2 mb-3">' +
        '<div><h1 class="text-lg font-bold text-slate-900 dark:text-white">' + icon + ' ' + esc(entry.file) + '</h1>' +
        '<p class="text-[12px] text-slate-400">' + esc(entry.dir) + ' · ' + fmtBytes(entry.size) + '</p></div>' +
        openRaw(rel, 'Open image') +
        '</div>' +
        '<img src="' + esc(imgSrc) + '" alt="' + esc(entry.file) + '" class="w-full rounded-xl border border-slate-200 dark:border-slate-700" onclick="openImageViewer(\'' + esc(rel.replace(/'/g, "\\'")) + '\')" style="cursor:zoom-in"></div>',
        { crumbs: crumbsForNavFromRel(entry) });
      attachDocNav(entry);
      return;
    }
    if (entry.kind === 'pdf') {
      app.innerHTML = shell(
        '<div class="card shadow-card p-4">' +
        '<div class="flex items-center justify-between flex-wrap gap-2 mb-3">' +
        '<div><h1 class="text-lg font-bold text-slate-900 dark:text-white">' + icon + ' ' + esc(entry.file) + '</h1>' +
        '<p class="text-[12px] text-slate-400">' + esc(entry.dir) + ' · ' + fmtBytes(entry.size) + '</p></div>' +
        openRaw(rel, 'Open PDF') +
        '</div>' +
        '<iframe src="' + esc(rel) + '" class="w-full h-[70vh] rounded-xl border border-slate-200 dark:border-slate-700" title="' + esc(entry.file) + '"></iframe></div>' +
        prevNextHtml(entry) + topicStripHtml(entry),
        { crumbs: crumbsForNavFromRel(entry) });
      return;
    }

    /* HTML + text documents — rendered inline as pages of this site, with an
       "Open HTML" button to view the original standalone file directly. */
    fetch(rel).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.text();
    }).then(function (raw) {
      var baseDir = entry.dir; /* site-relative: matches INDEX rel paths */
      var body, title;
      if (entry.ext === 'html' || entry.ext === 'htm') {
        var doc = new DOMParser().parseFromString(raw, 'text/html');
        doc.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(function (n) { n.remove(); });
        var card = doc.querySelector('.card') || doc.body;
        var h1 = card.querySelector('h1');
        title = ((doc.title || '').replace(/\s*·\s*studyUPSC\s*$/i, '') || (h1 ? h1.textContent : '') || entry.file.replace(/\.html?$/i, '')).trim();
        body = card.innerHTML;
      } else {
        title = entry.file.replace(/\.(md|txt|html?)$/i, '');
        body = mdToHtml(raw, baseDir);
      }
      var toc = mdToc(body);
      var words = body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().split(' ').length;
      var mins = Math.max(1, Math.round(words / 200));
      var appHtml = '<div class="grid lg:grid-cols-4 gap-8">' +
        '<div class="lg:col-span-3">' +
        '<div class="card shadow-card overflow-hidden">' +
        '<div class="relative px-5 sm:px-9 pt-6 pb-5 border-b border-slate-100 dark:border-slate-800">' +
        '<div class="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-indigo-500 via-violet-500 to-amber-400"></div>' +
        '<div class="flex items-start justify-between gap-3 flex-wrap">' +
        '<div class="min-w-0"><h1 class="font-display text-xl sm:text-2xl font-extrabold text-slate-900 dark:text-white leading-snug">' + esc(title) + '</h1>' +
        '<p class="text-[11px] text-slate-400 mt-1.5 font-mono">' + esc(entry.dir) + ' · ' + fmtBytes(entry.size) + ' · 🕐 ' + mins + ' min read</p></div>' +
        openRaw(rel, entry.ext === 'html' || entry.ext === 'htm' ? 'Open HTML' : 'Open file') +
        '</div></div>' +
        '<div class="md-content px-5 sm:px-9 py-7 max-w-none">' + body + '</div></div>' +
        (toc ? '<details class="toc-mobile card shadow-card mt-4"><summary>On this page</summary><div class="toc-mobile-body">' + toc + '</div></details>' : '') +
        prevNextHtml(entry) + topicStripHtml(entry) + '</div>' +
        (toc ? '<aside class="hidden lg:block"><div class="sticky top-24 card p-4 shadow-card toc-rail">' +
          '<div class="text-[10.5px] font-bold uppercase tracking-[0.14em] text-slate-400 mb-2">On this page</div>' + toc + '</div></aside>' : '') +
        '</div>';
      app.innerHTML = shell(appHtml, { crumbs: crumbsForNavFromRel(entry) });
      /* internal links/images inside the article stay inside the portal */
      rewriteInlineLinks($('.md-content'), baseDir);
      attachReadingProgress();
      attachTocHighlight();
      /* self-test mode for Q&A pages (shared engine from study.js) */
      try { if (window.Study) window.Study.quizify($('.md-content'), 'app|' + rel); } catch (e) { /* study.js optional */ }
      /* highlight search query if any */
      if (window._searchQuery) highlightInDoc(window._searchQuery);
    }).catch(function (err) {
      app.innerHTML = shell('<div class="rounded-2xl border border-red-200 dark:border-red-900 bg-red-50 dark:bg-red-900/20 p-6 text-sm text-red-700 dark:text-red-300 shadow-card">' +
        'Could not load <code class="code">' + esc(rel) + '</code> (' + esc(err.message) + ').<br>Regenerate the indexes with <code class="code">node cli/generate.mjs</code> and reload if the file was added recently.</div>',
        { crumbs: crumbsForNavFromRel(entry) });
    });
  }

  /* Resolve relative links/images inside an inlined article so that every
     click stays inside the SPA (routes to #/doc/…) and images resolve. */
  function rewriteInlineLinks(container, baseDir) {
    if (!container) return;
    container.querySelectorAll('a[href]').forEach(function (a) {
      var href = a.getAttribute('href') || '';
      if (!href || href.charAt(0) === '#') return;
      if (/^(https?:|mailto:|data:)/i.test(href)) { a.setAttribute('target', '_blank'); a.setAttribute('rel', 'noopener'); return; }
      var r = resolveHref(href, baseDir);
      if (r && entryByRel(r)) {
        a.setAttribute('href', '#/doc/' + encodeURIComponent(r));
        a.classList.add('md-internal');
      } else {
        a.setAttribute('href', r || href);
        a.setAttribute('target', '_blank');
        a.setAttribute('rel', 'noopener');
      }
    });
    container.querySelectorAll('img[src]').forEach(function (img) {
      var src = img.getAttribute('src') || '';
      if (/^(https?:|data:)/i.test(src)) return;
      img.setAttribute('src', resolveHref(src, baseDir));
      img.setAttribute('loading', 'lazy');
      img.classList.add('rounded-xl', 'border', 'border-slate-200', 'dark:border-slate-700', 'my-3', 'max-w-full');
    });
  }

  function crumbsForNavFromRel(entry) {
    var parts = entry.nav.split('/'), out = [], acc = [];
    parts.forEach(function (p) {
      acc.push(p);
      var n = NODE_BY_NAV[acc.join('/')];
      var isSec = SECTIONS.some(function (s) { return s.id === p; });
      out.push({ page: n ? (DATA.papers.some(function (pp) { return pp.nav === acc.join('/'); }) ? 'paper' : 'topic') : 'topic', nav: acc.join('/'), title: n ? n.title : (isSec ? sectionMeta(p).title : humanTitle(p)) });
    });
    return out;
  }

  /* Sibling documents across the whole topic (all sections), ordered
     detailed -> short -> points -> diagrams -> PYQs, so prev/next walks
     from notes to questions instead of dead-ending in a 1-file folder. */
  var TOPIC_SECTIONS = ['notes', 'short', 'bullets', 'diagrams', 'pyqs'];
  var SECTION_LABEL = {
    notes: ['📖', 'Detailed'], short: ['📝', 'Short notes'], bullets: ['🔹', 'Points'],
    diagrams: ['🗺️', 'Diagrams'], pyqs: ['❓', 'PYQs']
  };
  function topicSiblings(entry) {
    var parts = (entry.nav || '').split('/');
    var topicNav = entry.nav || '';
    if (parts.length > 1 && TOPIC_SECTIONS.indexOf(parts[parts.length - 1]) !== -1) {
      topicNav = parts.slice(0, -1).join('/');
    }
    var order = {};
    TOPIC_SECTIONS.forEach(function (s, i) { order[s] = i; });
    function secOf(nav) {
      var p = (nav || '').split('/');
      var last = p[p.length - 1];
      return order[last] != null ? order[last] : 99;
    }
    var sibs = INDEX.filter(function (f) {
      if (f.nav === topicNav) return true;
      if ((f.nav || '').indexOf(topicNav + '/') !== 0) return false;
      var rest = (f.nav || '').slice(topicNav.length + 1);
      // only direct section children — never deeper nested sub-topics
      return rest.indexOf('/') === -1 && TOPIC_SECTIONS.indexOf(rest) !== -1;
    });
    sibs.sort(function (a, b) {
      var sa = secOf(a.nav), sb = secOf(b.nav);
      if (sa !== sb) return sa - sb;
      return a.rel < b.rel ? -1 : 1;
    });
    return { topicNav: topicNav, sibs: sibs, idx: sibs.findIndex(function (f) { return f.rel === entry.rel; }) };
  }
  function prevNextHtml(entry) {
    var t = topicSiblings(entry);
    var prev = t.idx > 0 ? t.sibs[t.idx - 1] : null;
    var next = t.idx >= 0 && t.idx < t.sibs.length - 1 ? t.sibs[t.idx + 1] : null;
    if (!prev && !next) return '';
    return '<div id="doc-nav" class="flex items-center justify-between gap-3 mt-4">' +
      (prev ? '<a href="#/doc/' + encodeURIComponent(prev.rel) + '" class="btn-ghost text-[12px]">← ' + esc(shortName(prev.file)) + '</a>' : '<span></span>') +
      (next ? '<a href="#/doc/' + encodeURIComponent(next.rel) + '" class="btn-ghost text-[12px]">' + esc(shortName(next.file)) + ' →</a>' : '') + '</div>';
  }
  function topicStripHtml(entry) {
    var t = topicSiblings(entry);
    if (t.sibs.length < 2) return '';
    var chips = t.sibs.map(function (f) {
      var parts = (f.nav || '').split('/');
      var meta = SECTION_LABEL[parts[parts.length - 1]] || ['📄', humanTitle(parts[parts.length - 1])];
      if (f.rel === entry.rel) {
        return '<span class="topic-chip topic-chip-cur" aria-current="page">' + meta[0] + ' ' + esc(meta[1]) + '</span>';
      }
      return '<a class="topic-chip" href="#/doc/' + encodeURIComponent(f.rel) + '" title="' + esc(f.file) + '">' + meta[0] + ' ' + esc(meta[1]) + '</a>';
    }).join('');
    return '<div class="topic-strip card shadow-card mt-4"><div class="topic-strip-label">More in this topic</div>' +
      '<div class="topic-strip-row">' + chips + '</div></div>';
  }
  function shortName(f) { return f.replace(/\.(md|txt|html?)$/i, '').replace(/[-_]/g, ' ').slice(0, 42); }

  /* reading progress bar (top of viewport, document view only) */
  function attachReadingProgress() {
    var bar = $('#doc-progress');
    if (!bar) return;
    function paint() {
      if (!document.querySelector('.md-content')) { bar.classList.remove('on'); window.removeEventListener('scroll', paint); return; }
      var el = $('.md-content');
      var rect = el.getBoundingClientRect();
      var total = rect.height - window.innerHeight;
      var done = Math.min(Math.max(-rect.top, 0), Math.max(total, 1));
      bar.querySelector('div').style.width = (total > 0 ? Math.round(100 * done / total) : 0) + '%';
      bar.classList.toggle('on', rect.top < 0);
    }
    window.addEventListener('scroll', paint, { passive: true });
    paint();
  }
  /* highlight the TOC entry of the heading currently in view */
  function attachTocHighlight() {
    var links = $$('.toc-rail a');
    if (!links.length || !('IntersectionObserver' in window)) return;
    var byId = {};
    links.forEach(function (l) { byId[l.getAttribute('href').slice(1)] = l; });
    var obs = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting && byId[en.target.id]) {
          links.forEach(function (l) { l.classList.remove('active'); });
          byId[en.target.id].classList.add('active');
        }
      });
    }, { rootMargin: '-80px 0px -70% 0px' });
    Object.keys(byId).forEach(function (id) {
      var h = document.getElementById(id);
      if (h) obs.observe(h);
    });
  }

  /* ------------------------------------------------------------------ */
  /*  Markdown renderer (safe — HTML is escaped first)                    */
  /* ------------------------------------------------------------------ */
  function resolveHref(href, baseDir) {
    if (!href) return href;
    if (/^(#|https?:|mailto:|data:)/.test(href)) return href;
    if (href.charAt(0) === '/') return href;
    var p = (baseDir ? baseDir + '/' : '') + href;
    var segs = [], parts = p.split('/');
    parts.forEach(function (s) {
      if (s === '.' || s === '') return;
      if (s === '..') segs.pop();
      else segs.push(s);
    });
    return segs.join('/');
  }
  function mdInline(text, baseDir) {
    return text
      .replace(/`([^`]+)`/g, '<code class="code-inline">$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>')
      .replace(/!\[([^\]]*)\]\(([^)]+)\)/g, function (m, alt, src) {
        return '<img src="' + esc(resolveHref(src.trim(), baseDir)) + '" alt="' + esc(alt) + '" loading="lazy" class="rounded-xl border border-slate-200 dark:border-slate-700 my-3 max-w-full">';
      })
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, function (m, label, href) {
        var h = href.trim();
        var r = resolveHref(h, baseDir);
        var target = /^https?:/.test(r) ? ' target="_blank" rel="noopener"' : '';
        var cls = /\.(md|txt)$/i.test(r) ? ' class="md-internal"' : '';
        return '<a href="' + esc(r) + '"' + target + cls + '>' + label + '</a>';
      });
  }
  function mdToHtml(md, baseDir) {
    var lines = md.replace(/\r\n?/g, '\n').split('\n');
    var html = '', i = 0, inCode = false, codeLang = '', codeBuf = [], tableBuf = [];
    function flushTable() {
      if (!tableBuf.length) return;
      var rows = tableBuf.filter(function (r) { return r.trim() && !/^\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)*\|?\s*$/.test(r.trim()); });
      if (rows.length) {
        html += '<div class="overflow-x-auto my-3"><table class="w-full text-sm border-collapse">';
        rows.forEach(function (r, ri) {
          var cells = r.replace(/^\||\|$/g, '').split('|').map(function (c) { return c.trim(); });
          html += '<tr>';
          cells.forEach(function (c) {
            var tag = ri === 0 ? 'th' : 'td';
            html += '<' + tag + ' class="border border-slate-200 dark:border-slate-700 px-3 py-1.5 text-left ' + (ri === 0 ? 'bg-slate-50 dark:bg-slate-800 font-semibold' : '') + '">' + mdInline(c, baseDir) + '</' + tag + '>';
          });
          html += '</tr>';
        });
        html += '</table></div>';
      }
      tableBuf = [];
    }
    for (; i < lines.length; i++) {
      var line = lines[i];
      if (inCode) {
        if (/^```/.test(line.trim())) { inCode = false; html += '<pre class="code-block"><code' + (codeLang ? ' data-lang="' + esc(codeLang) + '"' : '') + '>' + esc(codeBuf.join('\n')) + '</code></pre>'; codeBuf = []; }
        else codeBuf.push(line);
        continue;
      }
      if (/^```/.test(line.trim())) { flushTable(); inCode = true; codeLang = line.trim().slice(3).trim(); codeBuf = []; continue; }
      if (/^\s*\|/.test(line)) { tableBuf.push(line); continue; }
      flushTable();
      var t = line.trim();
      if (!t) { html += '<div class="h-3"></div>'; continue; }
      var h = t.match(/^(#{1,4})\s+(.*)$/);
      if (h) {
        var lvl = h[1].length;
        html += '<h' + lvl + ' id="' + esc(slugifyHeading(h[2])) + '" class="md-h' + lvl + '">' + mdInline(h[2], baseDir) + '</h' + lvl + '>';
        continue;
      }
      if (/^---+$/.test(t)) { html += '<hr class="my-5 border-slate-200 dark:border-slate-700">'; continue; }
      if (/^>/.test(t)) {
        var quote = [];
        while (i < lines.length && /^>/.test(lines[i].trim())) { quote.push(lines[i].trim().replace(/^>\s?/, '')); i++; }
        i--;
        html += '<blockquote class="border-l-4 border-indigo-400 bg-indigo-50 dark:bg-indigo-900/20 pl-4 pr-3 py-2 my-3 rounded-r-lg text-slate-600 dark:text-slate-300">' + mdInline(quote.join(' '), baseDir) + '</blockquote>';
        continue;
      }
      if (/^[-*]\s+/.test(t) || /^\d+[.)]\s+/.test(t)) {
        var ordered = /^\d+[.)]/.test(t);
        var items = [];
        while (i < lines.length) {
          var li = lines[i];
          var mt = li.match(/^\s*([-*]|\d+[.)])\s+(.*)$/);
          if (!mt) break; /* leave i on the first non-list line */
          items.push(mt[2]);
          i++;
        }
        i--; /* back up one so the for-loop can continue correctly */
        html += (ordered ? '<ol class="list-decimal pl-6 my-3 space-y-1">' : '<ul class="list-disc pl-6 my-3 space-y-1">') +
          items.map(function (it) { return '<li class="md-li">' + mdInline(it, baseDir) + '</li>'; }).join('') +
          (ordered ? '</ol>' : '</ul>');
        continue;
      }
      html += '<p class="md-p">' + mdInline(t, baseDir) + '</p>';
    }
    if (inCode) { inCode = false; html += '<pre class="code-block"><code>' + esc(codeBuf.join('\n')) + '</code></pre>'; }
    flushTable();
    return html;
  }
  function slugifyHeading(s) {
    return s.toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-').slice(0, 60) || 'h';
  }
  function mdToc(body) {
    var out = '', re = /<h([234]) id="([^"]+)"[^>]*>([\s\S]*?)<\/h\1>/g, m;
    while ((m = re.exec(body))) {
      var depth = Number(m[1]);
      out += '<div class="' + (depth > 2 ? 'pl-' + (depth - 2) * 3 + ' ' : '') + '"><a href="#' + esc(m[2]) + '" class="block py-0.5 text-[13px]">' + m[3].replace(/<[^>]+>/g, '') + '</a></div>';
    }
    return out;
  }
  function highlightInDoc(q) {
    var walker = document.createTreeWalker($('.md-content'), NodeFilter.SHOW_TEXT);
    var nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(function (n) {
      var v = n.nodeValue, lq = q.toLowerCase();
      if (v.toLowerCase().indexOf(lq) === -1) return;
      var frag = document.createDocumentFragment();
      var idx = 0, pos;
      while ((pos = v.toLowerCase().indexOf(lq, idx)) !== -1) {
        frag.appendChild(document.createTextNode(v.slice(idx, pos)));
        var mark = document.createElement('mark');
        mark.className = 'bg-indigo-200/70 dark:bg-indigo-700/60 rounded px-0.5';
        mark.textContent = v.slice(pos, pos + q.length);
        frag.appendChild(mark);
        idx = pos + q.length;
      }
      frag.appendChild(document.createTextNode(v.slice(idx)));
      n.parentNode.replaceChild(frag, n);
    });
  }

  window.openImageViewer = function (rel) {
    var wrap = document.createElement('div');
    wrap.innerHTML = '<div class="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/90" role="dialog" aria-modal="true" data-imgclose>' +
      '<img src="' + esc(rel) + '" class="max-w-full max-h-[90vh] rounded-xl shadow-2xl">' +
      '<button class="absolute top-4 right-4 text-white/80 hover:text-white text-2xl w-10 h-10 rounded-full bg-white/10" data-imgclose>✕</button></div>';
    document.body.appendChild(wrap);
    function close() { wrap.remove(); }
    $$('[data-imgclose]', wrap).forEach(function (el) { el.addEventListener('click', close); });
    document.addEventListener('keydown', function escHandler(e) {
      if (e.key === 'Escape') { close(); document.removeEventListener('keydown', escHandler); }
    });
  };

  /* ------------------------------------------------------------------ */
  /*  Global search                                                       */
  /* ------------------------------------------------------------------ */
  var searchIndex = [];
  function buildSearchIndex() {
    searchIndex = [];
    /* syllabus topics */
    ALL_NODES.forEach(function (n) {
      searchIndex.push({ type: 'topic', nav: n.nav, title: n.title, tag: n.tag || '', path: n.nav, text: (n.title + ' ' + (n.tag || '') + ' ' + (n.summary || '')).toLowerCase() });
    });
    /* content dirs */
    DIRS.forEach(function (d) {
      var label = d.dir.split('/').pop();
      searchIndex.push({ type: 'folder', nav: d.nav, title: label, path: d.dir, text: (label + ' ' + d.dir).toLowerCase(), files: d.files.length });
    });
    /* files */
    INDEX.forEach(function (f) {
      searchIndex.push({ type: 'file', nav: f.nav, rel: f.rel, title: f.file, path: f.dir, kind: f.kind, text: (f.file + ' ' + f.dir).toLowerCase() });
    });
    /* full text */
    SEARCH_DOCS.forEach(function (d) {
      searchIndex.push({ type: 'text', nav: d.nav, rel: d.rel, title: d.file, path: d.rel, headings: d.headings || [], text: (d.text || '').toLowerCase(), chars: d.chars });
    });
  }

  var lastQuery = '';
  function searchAll(q) {
    q = q.trim().toLowerCase();
    lastQuery = q;
    if (!q) return [];
    var tokens = q.split(/\s+/);
    function match(text) { return tokens.every(function (t) { return text.indexOf(t) !== -1; }); }
    var scored = [];
    searchIndex.forEach(function (e) {
      var score = 0;
      var titleLower = e.title.toLowerCase();
      if (titleLower === q) score = 1000;
      else if (titleLower.indexOf(q) === 0) score = 500;
      else if (titleLower.indexOf(q) !== -1) score = 300;
      if (match(e.text)) score += 100;
      if (e.type === 'topic') score += 80;
      if (e.headings && e.headings.some(function (h) { return h.text.toLowerCase().indexOf(q) !== -1; })) score += 60;
      if (score > 0) scored.push({ e: e, score: score });
    });
    scored.sort(function (a, b) { return b.score - a.score; });
    return scored.slice(0, 60).map(function (s) { return s.e; });
  }

  window.openSearch = function (initialQ) {
    var wrap = document.createElement('div');
    wrap.id = 'search-modal';
    wrap.innerHTML =
      '<div class="fixed inset-0 z-[70]" role="dialog" aria-modal="true">' +
      '<div class="absolute inset-0 bg-slate-950/60 backdrop-blur-sm" data-sclose></div>' +
      '<div class="relative mx-auto mt-[10vh] w-[min(94vw,660px)] rounded-3xl bg-white dark:bg-slate-900 shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-800">' +
      '<div class="flex items-center gap-3 border-b border-slate-200 dark:border-slate-800 px-4">' +
      '<svg class="w-4 h-4 text-indigo-500" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path stroke-linecap="round" d="m21 21-4.3-4.3"/></svg>' +
      '<input id="search-input" type="text" placeholder="Search topics, notes, PYQs, diagrams…  (Esc to close)" class="w-full py-4 bg-transparent outline-none text-sm text-slate-900 dark:text-white placeholder-slate-400">' +
      '<kbd class="kbd">Esc</kbd></div>' +
      '<div id="search-results" class="max-h-[60vh] overflow-y-auto p-2"><div class="p-6 text-center text-sm text-slate-400">Type to search the whole syllabus, your notes and file names.</div></div>' +
      '<div class="border-t border-slate-200 dark:border-slate-800 px-4 py-2 text-[11px] text-slate-400 flex gap-4 bg-slate-50 dark:bg-slate-950/60"><span>↑↓ navigate</span><span>Enter open</span><span>' + searchIndex.length + ' indexed items</span></div></div></div>';
    document.body.appendChild(wrap);
    var input = $('#search-input', wrap);
    var results = $('#search-results', wrap);
    var active = -1;
    var currentResults = [];

    function renderResults(q) {
      currentResults = searchAll(q);
      active = currentResults.length ? 0 : -1;
      if (!q) { results.innerHTML = '<div class="p-6 text-center text-sm text-slate-400">Type to search the whole syllabus, your notes and file names.</div>'; return; }
      if (!currentResults.length) { results.innerHTML = '<div class="p-6 text-center text-sm text-slate-400">No results for “' + esc(q) + '”</div>'; return; }
      var html = '';
      var typeChip = { topic: 'bg-indigo-50 dark:bg-indigo-950/60 text-indigo-500 dark:text-indigo-300', folder: 'bg-slate-100 dark:bg-slate-800 text-slate-400', file: 'bg-emerald-50 dark:bg-emerald-950/50 text-emerald-500 dark:text-emerald-300', text: 'bg-amber-50 dark:bg-amber-950/50 text-amber-500 dark:text-amber-300' };
      currentResults.forEach(function (e, i) {
        var icon = e.type === 'topic' ? '📚' : e.type === 'folder' ? '📁' : e.type === 'file' ? (e.kind === 'image' ? '🖼️' : '📄') : '📝';
        var isPaper = e.type === 'topic' && DATA.papers.some(function (p) { return p.nav === e.nav; });
        var href = e.type === 'topic' ? '#/' + (isPaper ? 'paper' : 'topic') + '/' + encodeURIComponent(e.nav)
          : e.rel ? '#/doc/' + encodeURIComponent(e.rel)
            : e.nav ? '#/topic/' + encodeURIComponent(e.nav) : '#/';
        var snippet = '';
        if (e.type === 'text') {
          var idx = e.text.indexOf(q.toLowerCase());
          snippet = e.text.slice(Math.max(0, idx - 60), idx + 120);
          snippet = '…' + snippet.trim() + '…';
        }
        html += '<a href="' + href + '" data-i="' + i + '" class="search-item flex items-start gap-3 rounded-xl px-3 py-2.5 hover:bg-indigo-50/70 dark:hover:bg-indigo-950/30 ' + (i === active ? 'bg-indigo-50/70 dark:bg-indigo-950/30' : '') + '">' +
          '<span class="mt-0.5">' + icon + '</span>' +
          '<span class="min-w-0 flex-1"><span class="block text-sm font-medium text-slate-800 dark:text-slate-100 truncate">' + esc(e.title) + '</span>' +
          '<span class="block text-[11px] text-slate-400 truncate font-mono">' + esc(e.path || '') + '</span>' +
          (snippet ? '<span class="block text-[12px] text-slate-500 dark:text-slate-400 line-clamp-2 mt-0.5">' + esc(snippet) + '</span>' : '') +
          (e.headings && e.headings.length ? '<span class="block text-[11px] text-indigo-500 dark:text-indigo-400 truncate mt-0.5">' + e.headings.slice(0, 3).map(function (h) { return h.text; }).join(' · ') + '</span>' : '') +
          '</span>' +
          '<span class="chip ' + (typeChip[e.type] || '') + ' shrink-0 mt-1">' + e.type + '</span></a>';
      });
      results.innerHTML = html;
      $$('.search-item', results).forEach(function (el) {
        el.addEventListener('click', function () { close(); });
        el.addEventListener('mouseenter', function () { active = Number(el.dataset.i); paintActive(); });
      });
    }
    function paintActive() {
      $$('.search-item', results).forEach(function (el, i) {
        el.classList.toggle('bg-slate-100', i === active);
        el.classList.toggle('dark:bg-slate-700/50', i === active);
      });
    }
    function openActive() {
      if (currentResults[active] && currentResults[active].rel) {
        location.hash = '#/doc/' + encodeURIComponent(currentResults[active].rel);
        window._searchQuery = lastQuery;
      } else if (currentResults[active]) {
        location.hash = '#/topic/' + encodeURIComponent(currentResults[active].nav || currentResults[active].nav);
      }
      close();
    }
    function close() { wrap.remove(); }

    input.addEventListener('input', debounce(function () { renderResults(input.value); }, 60));
    input.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowDown') { e.preventDefault(); active = Math.min(active + 1, currentResults.length - 1); paintActive(); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); active = Math.max(active - 1, 0); paintActive(); }
      else if (e.key === 'Enter') { e.preventDefault(); openActive(); }
    });
    $$('[data-sclose]', wrap).forEach(function (el) { el.addEventListener('click', close); });
    document.addEventListener('keydown', function escHandler(e) {
      if (e.key === 'Escape') { close(); document.removeEventListener('keydown', escHandler); }
    });
    input.focus();
    /* prefill from param or #/search?q= */
    var initial = typeof initialQ === 'string' ? initialQ : '';
    if (!initial) {
      var m = location.hash.match(/[?&]q=([^&#]*)/);
      if (m) { try { initial = safeDecode(m[1].replace(/\+/g,' ')); } catch(e) { initial = m[1]; } }
    }
    if (initial) { input.value = initial; renderResults(initial); }
  }

  /* ------------------------------------------------------------------ */
  /*  Tracker page                                                        */
  /* ------------------------------------------------------------------ */
  function renderTracker() {
    var o = overallProgress();
    var html = '';
    html += '<div class="hero-shell relative overflow-hidden rounded-3xl bg-gradient-to-br from-indigo-950 via-slate-900 to-slate-900 text-white p-7 mb-6 shadow-lift">' +
      '<div class="hero-grid"></div>' +
      '<div class="relative z-10 flex flex-wrap items-center gap-6">' +
      '<div class="relative w-24 h-24">' +
      '<svg viewBox="0 0 100 100" class="w-24 h-24 -rotate-90"><circle cx="50" cy="50" r="42" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="10"/>' +
      '<circle cx="50" cy="50" r="42" fill="none" stroke="#818cf8" stroke-width="10" stroke-linecap="round" stroke-dasharray="' + (2 * Math.PI * 42) + '" stroke-dashoffset="' + (2 * Math.PI * 42 * (1 - o.pct / 100)) + '"/></svg>' +
      '<div class="absolute inset-0 flex items-center justify-center text-2xl font-extrabold">' + o.pct + '%</div></div>' +
      '<div class="flex-1"><h1 class="font-display text-2xl font-extrabold">✅ Revision Checklist</h1>' +
      '<p class="text-slate-300 text-sm mt-1">' + o.done + ' of ' + o.total + ' syllabus topics completed. Progress is saved in your browser (LocalStorage) and never leaves your device.</p></div>' +
      '<div class="flex gap-2 flex-wrap">' +
      '<button class="btn-ghost-light text-[12px]" onclick="exportProgress()">⬇ Export JSON</button>' +
      '<button class="btn-ghost-light text-[12px]" onclick="importProgress()">⬆ Import JSON</button>' +
      '<button class="btn-danger text-[12px]" onclick="resetProgress()">Reset all</button></div></div>';

    html += '<div class="grid lg:grid-cols-2 gap-6">';
    DATA.papers.forEach(function (paper) {
      var pr = paperProgress(paper);
      html += '<div class="card p-5 shadow-card">' +
        '<div class="flex items-center justify-between mb-1.5"><h2 class="font-display font-bold text-slate-900 dark:text-white">' + numBadge(paper.nav) + ' ' + esc(paper.title) + '</h2>' +
        '<span class="chip ' + (pr.pct === 100 ? 'bg-emerald-50 dark:bg-emerald-950/50 text-emerald-500' : 'bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-300') + '">' + pr.pct + '%</span></div>' +
        progressBar(pr.pct, pr.pct === 100 ? 'bg-emerald-500' : 'bg-gradient-to-r from-indigo-500 to-violet-500') +
        '<div class="mt-1.5 mb-3 text-[11px] text-slate-400">' + pr.done + '/' + pr.total + ' topics</div>' +
        trackerList(paper) + '</div>';
    });
    html += '</div>';
    $('#app').innerHTML = shell(html);
  }
  function trackerList(node) {
    var html = '<ul class="space-y-1">';
    function walk(n) {
      if (isLeaf(n)) {
        html += '<li class="flex items-center gap-2.5 rounded-lg px-2 py-1.5 hover:bg-slate-50 dark:hover:bg-slate-700/40">' + leafCheckbox(n.nav) +
          numBadge(n.nav, true) +
          '<span class="text-[13px] text-slate-700 dark:text-slate-200 ' + (progress[n.nav] === 1 ? 'line-through opacity-50' : '') + '">' + esc(n.title) + '</span></li>';
        return;
      }
      n.sub.forEach(walk);
    }
    node.sub.forEach(walk);
    html += '</ul>';
    return html;
  }
  window.exportProgress = function () {
    var blob = JSON.stringify(progress, null, 2);
    navigator.clipboard.writeText(blob).then(function () { toast('Progress JSON copied — paste into a backup file'); });
  };
  window.importProgress = function () {
    var wrap = document.createElement('div');
    wrap.innerHTML = '<div class="fixed inset-0 z-[70] flex items-center justify-center p-4">' +
      '<div class="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" data-iclose></div>' +
      '<div class="relative w-full max-w-md rounded-3xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xl p-5">' +
      '<h3 class="font-bold text-slate-900 dark:text-white mb-2">Import progress JSON</h3>' +
      '<textarea id="import-box" rows="6" class="w-full rounded-xl border border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-900 text-[12px] p-2 font-mono outline-none focus:border-indigo-400" placeholder=\'{&quot;gs-1/modern-history&quot;:1}\'></textarea>' +
      '<div class="flex gap-2 mt-3"><button class="btn-primary flex-1 justify-center text-[13px]" data-ido>Import</button>' +
      '<button class="btn-ghost text-[13px]" data-iclose>Cancel</button></div></div></div>';
    document.body.appendChild(wrap);
    function close() { wrap.remove(); }
    $$('[data-iclose]', wrap).forEach(function (el) { el.addEventListener('click', close); });
    $('[data-ido]', wrap).addEventListener('click', function () {
      try {
        var obj = JSON.parse($('#import-box', wrap).value);
        if (typeof obj !== 'object' || obj === null) throw new Error('not an object');
        progress = obj;
        saveProgress();
        close();
        renderSidebar(); render(); updateFavicon();
        toast('Progress imported ✓');
      } catch (e) { toast('Invalid JSON — could not import'); }
    });
  };
  window.resetProgress = function () {
    if (!confirm('Reset ALL revision progress? This cannot be undone.')) return;
    progress = {};
    saveProgress();
    renderSidebar(); render(); updateFavicon();
    toast('Progress reset');
  };

  /* ------------------------------------------------------------------ */
  /*  Misc pages                                                          */
  /* ------------------------------------------------------------------ */
  function renderNotFound(nav, kind) {
    $('#app').innerHTML = shell(
      '<div class="card border-dashed p-10 text-center shadow-card">' +
      '<div class="text-5xl mb-3">🗺️</div>' +
      '<h1 class="text-xl font-bold text-slate-900 dark:text-white mb-2">Nothing here yet</h1>' +
      '<p class="text-sm text-slate-500 dark:text-slate-400 mb-4">The ' + (kind === 'doc' ? 'document' : 'topic') + ' <code class="code">' + esc(nav) + '</code> is not in the syllabus tree.</p>' +
      '<div class="flex justify-center gap-2 mt-2"><a href="#/" class="btn-primary inline-flex">← Back to dashboard</a> <button class="btn-ghost" onclick="openSearch()">Search</button></div></div>');
  }

  function renderSearchPage(q) {
    if (q) window._searchQuery = q;
    openSearch(q);
    $('#app').innerHTML = shell('<div class="text-center py-20 text-slate-400 text-sm">Searching' + (q ? ' for “' + esc(q) + '”' : '') + '…</div>');
  }

  /* ------------------------------------------------------------------ */
  /*  Toasts & keyboard                                                   */
  /* ------------------------------------------------------------------ */
  function toast(msg) {
    var t = document.createElement('div');
    t.className = 'fixed bottom-5 left-1/2 -translate-x-1/2 z-[90] rounded-full bg-indigo-600 dark:bg-indigo-500 text-white text-[13px] px-4 py-2 shadow-lift animate-fade-up';
    t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(function () { t.remove(); }, 2200);
  }

  /* ------------------------------------------------------------------ */
  /*  Render dispatcher                                                   */
  /* ------------------------------------------------------------------ */
  function render() {
    var r = parseHash();
    var app = $('#app');
    if (!app) return;
    window.scrollTo(0, 0);
    // Expand sidebar to current route and sync active states
    if (r.nav) expandTo(r.nav);
    else if (r.rel) {
      var e = entryByRel(r.rel);
      if (e && e.nav) expandTo(e.nav);
    }
    syncTopNavActive(r);
    // Always re-render sidebar so active + expanded states stay correct
    // (cheap: sidebar is small DOM)
    try { renderSidebar(); } catch(e2) {}
    if (r.page === 'home') renderHome();
    else if (r.page === 'paper') renderPaper(r.nav);
    else if (r.page === 'topic') {
      // Tolerate cross-routed links: if topic nav is actually a paper, render paper
      var n = r.nav ? NODE_BY_NAV[r.nav] : null;
      if (n && !isLeaf(n) && r.section == null) {
        // Non-leaf requested via /topic -> render as paper for robustness
        renderPaper(r.nav);
      } else {
        renderTopic(r.nav, r.section);
      }
    }
    else if (r.page === 'doc') renderDoc(r.rel);
    else if (r.page === 'tracker') renderTracker();
    else if (r.page === 'search') renderSearchPage(r.q);
    else renderHome();
    // Focus main for a11y, update document title, close mobile sidebar on nav
    try {
      var main = document.getElementById('app');
      if (main) { main.focus({ preventScroll: true }); }
    } catch(e3){}
    updateDocumentTitle(r);
    closeSidebar();
  }
  function updateDocumentTitle(r){
    var base='studyUPSC — UPSC CSE Preparation';
    try{
      if(!r || r.page==='home') document.title=base;
      else if(r.page==='tracker') document.title='Tracker · '+base;
      else if(r.page==='search') document.title=(r.q? 'Search: '+r.q+' · ':'Search · ')+base;
      else if(r.nav && NODE_BY_NAV[r.nav]) document.title=NODE_BY_NAV[r.nav].title+' · '+base;
      else if(r.rel) document.title=(entryByRel(r.rel)?.file || r.rel)+' · '+base;
      else document.title=base;
    }catch(e){}
  }

  /* ------------------------------------------------------------------ */
  /*  Init                                                                */
  /* ------------------------------------------------------------------ */
  function init() {
    buildSearchIndex();
    applyTheme();
    // Expand sidebar to initial route before first paint
    try {
      var initR = parseHash();
      if (initR.nav) expandTo(initR.nav, true);
      else if (initR.rel) { var ee=entryByRel(initR.rel); if(ee&&ee.nav) expandTo(ee.nav, true); }
    } catch(e){}
    renderSidebar();
    render();
    updateFavicon();

    /* delegation: sidebar expand/chevrons + tracker checkboxes */
    document.addEventListener('click', function (e) {
      var expandEl = e.target.closest('[data-expand]');
      if (expandEl) {
        // If the click was on the anchor inside the expand row, don't also toggle
        // when user intended to navigate — but toggling is still expected on row click
        var isLink = e.target.closest('a[href]');
        if (isLink && isLink.closest('[data-expand]') === expandEl) {
          // Allow navigation, but also ensure the group expands
          var k = expandEl.dataset.expand;
          if (!expanded[k]) { expanded[k]=1; try{localStorage.setItem(EXPAND_KEY, JSON.stringify(expanded));}catch(e){} }
          return;
        }
        setExpanded(expandEl.dataset.expand, !expanded[expandEl.dataset.expand]);
        return;
      }
      var dn = e.target.closest('[data-done-next]');
      if (dn) {
        var dnav = dn.getAttribute('data-done-next');
        if (progress[dnav] !== 1) { progress[dnav] = 1; saveProgress(); }
        renderSidebar();
        updateFavicon();
        var ni = leafIndex(dnav);
        if (ni >= 0 && ni < LEAVES.length - 1) go('#/topic/' + encodeURIComponent(LEAVES[ni + 1].nav));
        else go('#/tracker');
        return;
      }
      var cb = e.target.closest('.tracker-cb');
      if (cb) {
        e.preventDefault();
        toggleNode(cb.dataset.nav);
        return;
      }
      /* Q&A cards inlined from documents: show/hide all answers */
      var qaBtn = e.target.closest && e.target.closest('[data-qa]');
      if (qaBtn) {
        var open = qaBtn.getAttribute('data-qa') === 'show';
        $$('.qa-a').forEach(function (d) { d.open = open; });
        return;
      }
      var mdInternal = e.target.closest('.md-internal');
      if (mdInternal) { e.preventDefault(); location.hash = '#/doc/' + encodeURIComponent(mdInternal.getAttribute('href')); return; }
      /* in-page anchors (TOC rail, mobile TOC, heading links): smooth-scroll
         instead of letting the hash router treat them as app routes */
      var anchor = e.target.closest && e.target.closest('a[href^="#"]');
      if (anchor) {
        var href = anchor.getAttribute('href') || '';
        if (href.length > 1 && href.charAt(1) !== '/') {
          var target = document.getElementById(href.slice(1));
          if (target) {
            // Scroll only — the app-route hash stays untouched so reload
            // and back/forward keep working.
            e.preventDefault();
            if (typeof target.scrollIntoView === 'function') {
              try { target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
              catch (err) { try { target.scrollIntoView(); } catch (e2) { /* noop */ } }
            }
          }
          return;
        }
      }
    });
    // Keyboard: Enter/Space on expand rows
    document.addEventListener('keydown', function(e){
      var el = e.target.closest('[data-expand]');
      if(el && (e.key==='Enter' || e.key===' ')){
        e.preventDefault();
        setExpanded(el.dataset.expand, !expanded[el.dataset.expand]);
      }
    });

    /* mobile sidebar */
    var sb = $('#sidebar');
    var overlay = $('#sidebar-overlay');
    if (overlay) overlay.addEventListener('click', closeSidebar);
    var btn = $('#sidebar-toggle');
    if (btn) btn.addEventListener('click', toggleSidebar);

    /* theme */
    var tb = $('#theme-toggle');
    if (tb) tb.addEventListener('click', toggleTheme);

    window.addEventListener('hashchange', render);

    document.addEventListener('keydown', function (e) {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); openSearch(); }
      else if (e.key === '/' && !/input|textarea|select/i.test(document.activeElement.tagName)) { e.preventDefault(); openSearch(); }
      else if (e.key === 'Escape' && document.body.classList.contains('sidebar-open')) { closeSidebar(); }
    });
  }

  function expandTo(nav, silent) {
    if (!nav) return;
    nav = normalizeNav(nav);
    var parts = nav.split('/'), acc = [];
    parts.forEach(function (p) {
      acc.push(p);
      var key = 'n:' + acc.join('/');
      if (NODE_BY_NAV[acc.join('/')]) expanded[key] = 1;
    });
    /* expand the paper */
    var paper = DATA.papers.find(function (p) { return nav === p.nav || nav.indexOf(p.nav + '/') === 0; });
    if (paper) expanded['p:' + paper.id] = 1;
    // Also expand file tree ancestors if nav is file-like (content/...) — no-op for syllabus navs
    if (!silent) {
      try { localStorage.setItem(EXPAND_KEY, JSON.stringify(expanded)); } catch(e){}
    }
  }

  function toggleSidebar() {
    var open = document.body.classList.toggle('sidebar-open');
    var btn = document.getElementById('sidebar-toggle');
    if (btn) btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    try { localStorage.setItem('studyupsc-sidebar-open', open ? '1' : '0'); } catch(e){}
  }
  function closeSidebar() {
    document.body.classList.remove('sidebar-open');
    var btn = document.getElementById('sidebar-toggle');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
